(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c66"]=[{"id":"00004591","register_sub_id":"101","register_pk":"105581","name":"瀬川家住宅主屋","kana":"せがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通御前通西入堀川町522","lat":35.0210314,"lng":135.73357531,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0190","desc":"妙心寺道に北面して建つ。つし２階建，切妻造，桟瓦葺で，両側面にうだつを設ける。正面２階は漆喰塗で，虫籠窓を開ける。内部は基本的に西半を居室，東半を土間とする。桁行方向に貫を用いない小屋組，２階座敷がないことなど，江戸後期の町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004591"},{"id":"00004592","register_sub_id":"101","register_pk":"105582","name":"瀬川家住宅土蔵","kana":"せがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通御前通西入堀川町522","lat":35.02097211,"lng":135.73363755,"geo_status":"db","era":"宝永7頃","year":1710,"year_source":"db","year_min":1710,"year_max":1710,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0191","desc":"主屋の南東にある。土蔵造２階建，東西棟の切妻造，桟瓦葺で，東妻面は街路に面している。北面１階には観音開きの扉をつけ，深い庇を掛ける。外壁は漆喰塗とし，２階まで高く縦板張で覆う。階段板に宝永７年の墨書があり，建築年代がほぼ明確な数少ない土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004592"},{"id":"00011735","register_sub_id":"101","register_pk":"210751","name":"千歳家住宅旧蔵","kana":"せんざいけじゅうたくきゅうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区阿波橋町401他","lat":34.932236,"lng":135.755582,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0524","desc":"主屋後方、離れの北側に南北棟で建つ。桁行五メートル梁間四・九メートル、土蔵造二階建、切妻造桟瓦葺である。水害対策の石積基礎に建ち、外壁漆喰塗で腰高に竪板を張り、東面を戸口として繰型のある持送付きの庇を付す。旧家の屋敷構えを構成する家財蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011735"},{"id":"00011733","register_sub_id":"101","register_pk":"210749","name":"千歳家住宅主屋","kana":"せんざいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区阿波橋町401他","lat":34.932197,"lng":135.755796,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積246㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0522","desc":"濠川西側の通りに東面する。正面北側に出格子を設け、南側は舟板竪張とし、内部に二間幅の土間を通す。つし二階は漆喰塗で格子窓を穿つ。床上部は下手のチョウバ等と上手の座敷列を廊下で画し、座敷飾や建具も上質である。伏見の商家の構えを伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011733"},{"id":"00011736","register_sub_id":"101","register_pk":"210752","name":"千歳家住宅新蔵","kana":"せんざいけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区阿波橋町401他","lat":34.932294,"lng":135.755595,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0525","desc":"主屋後方、旧蔵の北側に東西棟で建つ。桁行四・九メートル梁間四・一メートル、土蔵造二階建、切妻造桟瓦葺である。旧蔵同様に水害対策の石積基礎に建ち、外壁を人造石洗い出し仕上げとする。南面を戸口として、一階東面、二階東・南面に窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011736"},{"id":"00011734","register_sub_id":"101","register_pk":"210750","name":"千歳家住宅離れ","kana":"せんざいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区阿波橋町401他","lat":34.932171,"lng":135.75557,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0523","desc":"主屋の西奥に渡り廊下を介して建つ。切妻造桟瓦葺で、南・西縁に下屋を廻らす。七畳主室と一部舟底天井の四畳からなり、主室では床と違棚を矩折れに配し、床脇に円窓を穿つ。独特な鉈目の床柱、違棚の青海波彫刻など、大工の独創が看取される数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011734"},{"id":"00000414","register_sub_id":"101","register_pk":"101404","name":"大雲院書院（旧大倉家京都別邸）","kana":"だいうんいんしょいん（きゅうおおくらけきょうとべってい）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側594-1","lat":35.00237478,"lng":135.77998109,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造・鉄筋コンクリート造2階建，瓦葺，建築面積234㎡","structure_material":"木造・鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"26 － 0011","desc":"もと大倉家の別邸で，寝室及び納戸のみ鉄筋コンクリート造とし，その他を木造とする。全体に吟味された良材を用い，洗練された技法になる質の高い和風住宅で，特に内部を八角形状に仕上げた応接室は見応えがある。設計は伊東忠太，施工は大倉土木。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000414"},{"id":"00012957","register_sub_id":"101","register_pk":"368037","name":"高田家住宅主屋","kana":"たかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区出雲路立テ本町103-4","lat":35.03856667,"lng":135.76478889,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡、地下室付","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"26 － 588","desc":"鴨川西岸の敷地に東面して建つ寄棟造桟瓦葺の二階建。正面に三面アーチの玄関ポーチを張出す。上下階とも中廊下を境に和洋室を分け、一階の北側に応接、食堂など洋間、南側に座敷、仏間など和室を配する。外観も南北で和洋意匠を使い分けた瀟洒な郊外住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012957"},{"id":"00005995","register_sub_id":"101","register_pk":"106980","name":"竹澤家住宅主屋","kana":"たけざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町島英サ26","lat":35.26612112,"lng":135.54910684,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"26 － 0224","desc":"敷地の中央に東面して建つ。桁行６間，梁間５間規模，木造平屋建，平入，入母屋造の茅葺で，正面と両側面に鉄板葺の下屋を設ける。平面は土間に厩を設け，床上部は食違い四間取で，台所，座敷２室及び寝間とする。棟を鞍掛の形状とし，地域の特徴ある景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005995"},{"id":"00009339","register_sub_id":"101","register_pk":"194132","name":"田村家住宅井戸屋形","kana":"たむらけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府長岡京市長法寺南谷11","lat":34.93178167,"lng":135.67981492,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、面積3.6㎡、石垣付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0412","desc":"離れと茶室の中間に位置する桁行二・五メートル梁間一・四メートルの木造平屋建、寄棟造桟瓦葺。北寄りに井筒があり、棟木に滑車を吊る。西面は吹放ちとし、他の三面は上半を開放、腰壁は内面に貫を見せる板壁で、外面は割竹を竪張として外観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009339"},{"id":"00009338","register_sub_id":"101","register_pk":"194131","name":"田村家住宅茶室任無亭","kana":"たむらけじゅうたくちゃしつにんむてい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市長法寺南谷11","lat":34.93183473,"lng":135.67974306,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺一部瓦葺、建築面積16㎡、石垣付","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0411","desc":"一段高い敷地北半の東寄りに建つ。木造平屋建、宝形造茅葺及び桟瓦葺。四畳半の南面に濡縁をつけて貴人口とし、西面躙口上部は下地窓とする。東面も障子建てで眺望を得る。北面西半の下屋へ給仕口を開き、西へ瓦葺水屋を突出す。平明な意匠の茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009338"},{"id":"00012386","register_sub_id":"101","register_pk":"531710","name":"智慧夢工房二九研究所主屋","kana":"ちえゆめこうぼうふたくけんきゅうじょしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市南区唐橋川久保町29","lat":34.97845278,"lng":135.73654444,"geo_status":"db","era":"大正4年／平成28年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積140㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"26-570","desc":"九条通に南面して建つ。間口五間半のつし二階建で、正面に出格子を立て、虫籠窓を二所穿つ。玄関奥に吹抜の玄関庭を配して屋根の一部を切欠く。床上部は二列構成で、上手奥を十畳座敷とし、幅広の床脇など座敷飾も洗練される。京都市南郊の良質な大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012386"},{"id":"00012387","register_sub_id":"101","register_pk":"531711","name":"智慧夢工房二九研究所土蔵","kana":"ちえゆめこうぼうふたくけんきゅうじょどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市南区唐橋川久保町29","lat":34.97856111,"lng":135.73648056,"geo_status":"db","era":"明治36年／平成28年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"26-571","desc":"主屋後方西寄りに南北棟で建つ。桁行4･9メートル梁間4メートル、土蔵造、外壁漆喰塗で鉢巻を廻らし、北・西面に腰高に竪板を張る。東面に下屋を設けて戸口を開き、二階の小窓に繰形を施す持送付の庇をかける。伝統的な町家の屋敷構えに寄与する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012387"},{"id":"00004995","register_sub_id":"101","register_pk":"105985","name":"十四春主屋","kana":"としはるしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区諏訪町通松原下る弁財天町326","lat":34.99842883,"lng":135.75866693,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積107㎡、塀延長12m付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0204","desc":"烏丸五条の交差点の北西，諏訪町通に東面する。通り側に間口１０ｍの高塀を配し，やや奥に主屋を構える。内部は随所に銘木をあしらい，趣の異なる複数の座敷を北半に配す。高塀は，腰竪板張，上部真壁で出格子窓を付す端正なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004995"},{"id":"00004996","register_sub_id":"101","register_pk":"105986","name":"十四春土蔵","kana":"としはるどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区諏訪町通松原下る弁財天町326","lat":34.99846617,"lng":135.75854262,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0205","desc":"東西に細長い敷地の北西角に建つ。切妻造，平入，本瓦葺の土蔵造２階建で，一階庇で深い軒をつくり，軒裏には鉢巻を廻らす。開口部廻りを掛子塗とし，戸口は上部に黒漆喰を塗り込み，門構風に見せる。裏庭に面し，屋敷構を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004996"},{"id":"00002412","register_sub_id":"101","register_pk":"103402","name":"仲家住宅主屋","kana":"なかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区室町通御池上る御池之町322","lat":35.01125402,"lng":135.75811055,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積106㎡、正面高塀付","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"26 － 0089","desc":"室町通の東側に位置し，通りに面して建つ高塀の奥に座敷を繋げるいわゆる高塀造の町家。高塀に接して平屋の応接間，その奥に２階建，通り土間をもつ居室部を配す。島原角屋（重要文化財）を参考にしたといい，座敷飾りや窓回りの随所に凝った意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002412"},{"id":"00002413","register_sub_id":"101","register_pk":"103403","name":"仲家住宅土蔵","kana":"なかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区室町通御池上る御池之町322","lat":35.01125309,"lng":135.75826618,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"26 － 0090","desc":"主屋の背後，短冊型の敷地の東端に建つ。土蔵造，２階建，本瓦葺で，現在トタンで囲われているが，外部は漆喰塗で仕上げる。小規模な蔵だが，半間毎に柱を建て，戸口には精巧な鉄扉を構え，各窓には持送り付きの瓦葺庇を設けるなど，本格的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002413"},{"id":"00007072","register_sub_id":"101","register_pk":"108054","name":"中小路家住宅内蔵","kana":"なかこうじけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.93587499,"lng":135.70038883,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0294","desc":"主屋の西に位置する東西棟の２階建土蔵で、南に蔵前を設け、主屋に通じる。桁行３．９ｍ梁間４．２ｍ。鉢巻上に切妻造桟瓦葺の置屋根を載せ、一連で塗り込める。外壁は漆喰仕上げとし、高く腰板を張る。内部は壁板張で、和小屋とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007072"},{"id":"00007077","register_sub_id":"101","register_pk":"108059","name":"中小路家住宅木小屋及び塀","kana":"なかこうじけじゅうたくきごやおよびへい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.9359872,"lng":135.70070896,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木小屋 木造平屋建、瓦葺、建築面積4.0㎡ 塀 木造、瓦葺、延長5.4m","structure_material":"木小屋 木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0299","desc":"長屋門から旧西国街道沿いに北へ塀が延びる。塀は腰板壁上部漆喰壁で、屋根桟瓦葺。木小屋は敷地東北隅に東西棟で建つ。屋根桟瓦葺で、東を入母屋造、西を切妻造とし、街道側を腰板張漆喰壁とする。穀蔵や長屋門とともに一体となり、伝統的な街道景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007077"},{"id":"00007075","register_sub_id":"101","register_pk":"108057","name":"中小路家住宅穀蔵","kana":"なかこうじけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.93577656,"lng":135.70074003,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0297","desc":"旧西国街道沿いに南北棟で建つ。切妻造桟瓦葺の２階建土蔵で、西側に庇を付設。桁行９．０ｍ梁間３．９ｍで、内部は桁行に２分され、南を小屋、北を米蔵とする。外壁は軒までを塗り込める漆喰仕上げで、腰板壁とし、小屋側に横連子窓、米蔵に庇付窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007075"},{"id":"00007071","register_sub_id":"101","register_pk":"108053","name":"中小路家住宅主屋","kana":"なかこうじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.93592968,"lng":135.70053268,"geo_status":"db","era":"弘化5／昭和39改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0293","desc":"旧西国街道に東面する敷地の中央北寄りに建つ。切妻造桟瓦葺、桁行５間半梁間３間半の上屋に、西に１間の下屋、東に縁や式台を付設。南にもと土間のニワ、北に喰違いに居室が５室配され、座敷にトコ、棚を構える。質の高い座敷をもつ、規模の大きな農家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007071"},{"id":"00007076","register_sub_id":"101","register_pk":"108058","name":"中小路家住宅長屋門","kana":"なかこうじけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.93586017,"lng":135.70074072,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積4.1㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0298","desc":"主屋正面のやや南寄り、旧西国街道に面して建つ。桁行４．７ｍ梁間２．２ｍ、南側に潜戸付の両開板戸をたて門口とし、北側に２畳部屋を置く。屋根は桟瓦葺で、北が入母屋造、南は穀蔵に接続する。腰板張の白漆喰壁で、部屋に出格子窓を設け、軽快な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007076"},{"id":"00007074","register_sub_id":"101","register_pk":"108056","name":"中小路家住宅離れ及び内門","kana":"なかこうじけじゅうたくはなれおよびうちもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府向日市上植野町下川原48","lat":34.93582668,"lng":135.7006463,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"離れ 木造平屋建、瓦葺、建築面積20㎡ 内門 木造、瓦葺、面積9.0㎡","structure_material":"離れ 木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0296","desc":"離れは主屋東南に位置する。東西棟の切妻造桟瓦葺で、北面に庇を付ける。外壁は腰板張の漆喰塗、内部を居室として利用する。主屋との間に内門と称する、桁行６．０ｍ梁間１．４ｍの建物を庇と連続して設ける。西面を開放、東面を漆喰壁とし、一部を潜門とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007074"},{"id":"00008304","register_sub_id":"101","register_pk":"133946","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市調子1-31・32・33・34合併","lat":34.91387943,"lng":135.6925516,"geo_status":"db","era":"江戸末期／昭和26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積194㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"26 － 0348","desc":"旧西国街道に北面して建つ。建築面積１９４㎡、木造つし２階、切妻造桟瓦葺で、西側に寄棟造の下屋を付ける。正面中央を土間の出入口とし、東側のゲンカン、コウシノマに出格子をたて、上屋は漆喰を塗り込め、虫籠窓を穿つ。旧街道沿いに残る大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008304"},{"id":"00008305","register_sub_id":"101","register_pk":"133947","name":"中野家住宅茶室","kana":"なかのけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府長岡京市調子1-31・32・33・34合併","lat":34.91385336,"lng":135.69275678,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積31㎡","structure_material":"木造平屋一部2階建","registered":"2010.09.10(平成22.09.10)","register_no":"26 － 0349","desc":"皎庵と称し、敷地東面の土蔵に接続する。建築面積３１㎡、木造平屋一部２階建、入母屋造及び切妻造桟瓦葺である。四畳半茶席の西隅にトコと平書院を備え、四分割した網代天井はトコ前を高く、給仕口を低め、照明を設ける。数寄屋大工北村伝兵衛による近代茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008305"},{"id":"00008306","register_sub_id":"101","register_pk":"133948","name":"中野家住宅土蔵","kana":"なかのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府長岡京市調子1-31・32・33・34合併","lat":34.91382392,"lng":135.69273996,"geo_status":"db","era":"江戸末期／昭和26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"26 － 0350","desc":"敷地の東面、茶室と居室棟の間に建つ。桁行４．３ｍ梁間４．５ｍ、土蔵造２階建、切妻造桟瓦葺で、北面を出入口とし、蔵前を附属する。外壁は漆喰仕上げで、２階北面中央に窓を穿つ。旧家の屋敷構えをよく伝え、茶室とともに良質な庭空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008306"},{"id":"00009335","register_sub_id":"101","register_pk":"194128","name":"中村家住宅上の蔵","kana":"なかむらけじゅうたくうえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府八幡市八幡山柴52","lat":34.88227783,"lng":135.70277017,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0408","desc":"敷地北西隅に建ち、桁行七・九メートル梁間五・九メートル、土蔵造二階建、切妻造桟瓦葺。東妻の戸口を土戸両開とし、蔵前を鉄板葺とする。外壁は漆喰塗で腰高に竪板を張り北面は水切瓦を付ける。西妻の上下階に庇付の窓を穿つ。社前の河岸景観に趣を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009335"},{"id":"00009336","register_sub_id":"101","register_pk":"194129","name":"中村家住宅表門","kana":"なかむらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府八幡市八幡山柴52","lat":34.88230996,"lng":135.70295339,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0409","desc":"敷地の北辺東寄りに道路から奥まって開く一間一戸の腕木門である。門口は二・一メートル。起り付きの切妻造桟瓦葺で一軒疎垂木とする。内側ではナグリ仕上の控柱が腕木を支える。門扉は両開板扉で、上部に筬欄間を飾る。小規模ながら丁寧な造作の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009336"},{"id":"00009334","register_sub_id":"101","register_pk":"194127","name":"中村家住宅大歌堂","kana":"なかむらけじゅうたくだいかどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府八幡市八幡山柴52","lat":34.88216124,"lng":135.70299384,"geo_status":"db","era":"大正6年頃／大正後期増築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0407","desc":"石清水八幡宮の東麓に敷地を構え、建築面積二三八平方メートルである。中央の平屋建東西棟の大広間は折上格天井の一五畳で、三畳上段の間と三畳書院がつき、南から西へ縁を廻らす。北に延びる起り屋根の西の間には数寄屋風の小室を並べる。上質な近代の書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009334"},{"id":"00003108","register_sub_id":"101","register_pk":"104098","name":"中村宗哲家住宅","kana":"なかむらそうてつけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区武者小路通新町西入西無車小路町603","lat":35.02787912,"lng":135.75539807,"geo_status":"db","era":"嘉永7","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"26 － 0140","desc":"京都西陣にある塗師の住宅で，南と西側に高塀を建て，通り庭を持つ町家の形式。安政３年（１８５６）の裏千家の増築を手がけた木村清兵衛が建て，柱は色付けを施した面皮柱や絞り丸太を使用するなど，数寄屋大工の作品らしい雰囲気が漂う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003108"},{"id":"00006545","register_sub_id":"101","register_pk":"107528","name":"中村治男家住宅土蔵","kana":"なかむらはるおけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区室町通寺之内上る三丁目上柳原町117","lat":35.035461,"lng":135.758331,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0263","desc":"主屋の表屋の北に並ぶ土蔵造２階建である。方２間の規模で，切妻屋根の平側を街路に見せる。入口は東の坪庭に面して設ける。外壁は白漆喰塗で，腰の下見板張は弁柄塗とし，１階に瓦葺庇が付く。街路側の１・２階に開いた窓が外観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006545"},{"id":"00005997","register_sub_id":"101","register_pk":"106982","name":"西尾家住宅主屋","kana":"にしおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町島英サ29","lat":35.26654811,"lng":135.54975438,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"26 － 0225","desc":"敷地の北東方に東面して建つ。桁行７間，梁間６間規模，木造平屋建，平入，入母屋造の茅葺で，四方に瓦葺の下屋を廻す。平面は土間に厩を設け，床上部を台所，座敷３室及び寝間２室とする。棟を鞍掛の形状とし，地域の特徴ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005997"},{"id":"00009989","register_sub_id":"101","register_pk":"196136","name":"西川家住宅主屋","kana":"にしかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町91-24他","lat":35.011064,"lng":135.78393894,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、銅瓦葺一部瓦葺、建築面積184㎡、門及び塀付","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0445","desc":"内装を和洋折衷とした応接間を通り沿いに配し、左右に門と塀をのばす。後方に渡廊下を介して建つ居住部は、中廊下式で庭に面して座敷を並べて縁を通し、数寄屋意匠を加味しつつ、幅広の板材を多用するなど贅沢な造作とする。市街地に残る上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009989"},{"id":"00004589","register_sub_id":"101","register_pk":"105579","name":"西川家住宅主屋","kana":"にしかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区衣笠総門町3-1","lat":35.03702279,"lng":135.72916314,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0188","desc":"金閣寺の南方に位置する。木造２階建で，外観は水平線を強調した深い軒や丸窓などモダニズムの意匠でまとめる。内部は基本的に上質で瀟洒なつくりの和室で構成されるが，洋風の応接室や階段室等にはモダニズムが反映されている。昭和初期の郊外住宅の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004589"},{"id":"00009990","register_sub_id":"101","register_pk":"196137","name":"西川家住宅土蔵","kana":"にしかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町91-24他","lat":35.01102594,"lng":135.78399412,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0446","desc":"主屋の南東側に南北棟で建つ。土蔵造二階建、桁行三・六メートル梁間三・一メートル、切妻造桟瓦葺で、西面の戸口に庇と鉄扉を設ける。外壁漆喰塗で鉢巻を廻らし、二階南面に窓を穿つ。南面壁を主屋の塀と一連の意匠として瓦屋根を葺き、屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009990"},{"id":"00004590","register_sub_id":"101","register_pk":"105580","name":"西川家住宅土蔵","kana":"にしかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区衣笠総門町3-1","lat":35.03712252,"lng":135.72910618,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積23㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0189","desc":"主屋の北西に建つ。外観は通例の土蔵と同様であるが，鉄筋コンクリート造の２階建で，屋根は切妻造，桟瓦葺，南面に庇を架け，１階戸口や２階窓に鉄扉を設ける。小屋組や床組は木造で，内壁も化粧板を張る。伝統的な形式を，近代の素材でつくりあげた事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004590"},{"id":"00009644","register_sub_id":"101","register_pk":"194640","name":"長谷川家住宅表門","kana":"はせがわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市南区東九条東札辻町5","lat":34.97516214,"lng":135.76275724,"geo_status":"db","era":"江戸末期／昭和10移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0423","desc":"敷地西辺、土蔵の北側に棟を落として接続する。桁行三・五メートル梁間三メートル、木造平屋建、切妻造桟瓦葺で、上部を内法の低い物置として東面に格子窓を穿つ。間口二メートルの門口に板戸を吊り、南側に潜戸を開く。土蔵と共に風格ある表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009644"},{"id":"00009642","register_sub_id":"101","register_pk":"194638","name":"長谷川家住宅主屋","kana":"はせがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市南区東九条東札辻町5","lat":34.97514405,"lng":135.76303921,"geo_status":"db","era":"寛保2／江戸後期・平成22改修","year":1742,"year_source":"db","year_min":1742,"year_max":1742,"year_label":null,"structure":"木造2階建、瓦葺、建築面積271㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0421","desc":"敷地中央に西面して建ち、切妻造桟瓦葺で、二階正面に横長の虫籠窓を設ける。南半の広い土間では重厚な梁組を現し、北半の床上部に二列六室を並べ、前面に洗練された意匠の角座敷を張出す。町家風の外観をもち、京都市南部で数少ない大型の近世民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009642"},{"id":"00009643","register_sub_id":"101","register_pk":"194639","name":"長谷川家住宅土蔵","kana":"はせがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市南区東九条東札辻町5","lat":34.97511193,"lng":135.76277152,"geo_status":"db","era":"江戸後期／昭和10移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0422","desc":"敷地西辺中央に南北棟で建ち、北側に表門を付属する。桁行五・八メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺である。東面を戸口として下屋を設け、外壁漆喰塗で軒裏まで塗込め、腰に竪板張と水切を廻らす。旧家の屋敷構えの名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009643"},{"id":"00015035","register_sub_id":"101","register_pk":"529313","name":"林家住宅主屋","kana":"はやしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府南丹市美山町高野三ノ尾27","lat":35.30498333,"lng":135.55873611,"geo_status":"db","era":"明治16年／昭和中期増築改修・令和4年改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積196㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0677","desc":"美山の山間集落の高台に位置し南面して建つ旧家の主屋。平屋建南北棟の入母屋造平入茅葺（鉄板仮葺）で南・西面に桟瓦葺下屋を付す。西に旧土間、東に6室を配し、南面西寄りに式台玄関を構え南西続き座敷境に彫刻欄間を飾る。大規模な主屋が地域景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015035"},{"id":"00010485","register_sub_id":"101","register_pk":"199435","name":"速水家住宅乾蔵","kana":"はやみけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町108他","lat":35.009328,"lng":135.764551,"geo_status":"db","era":"文久2(1862)","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0472","desc":"道具蔵の北隣に西面して建つ。桁行、梁間とも二間の小規模な二階建土蔵で、南北棟の切妻造桟瓦葺の平入とし、正面に下屋を架け、両開き扉を吊る。鉄板覆の外壁は漆喰塗が残り、腰は竪板で覆っている。家財を収納する蔵で、敷地後方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010485"},{"id":"00010483","register_sub_id":"101","register_pk":"199433","name":"速水家住宅主屋","kana":"はやみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町108他","lat":35.00924,"lng":135.764834,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0470","desc":"切妻造桟瓦葺の二階建で、表屋造形式の町家である。表屋は一階が土間と二室、二階が二室で、玄関棟が続く。奥の居住棟は片側が吹抜の通り土間で、上下階とも一列三室とする。全体の二階化や広い開口部、大きな袖壁設置など、近代町家の発展過程を示す好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010483"},{"id":"00010484","register_sub_id":"101","register_pk":"199434","name":"速水家住宅道具蔵","kana":"はやみけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市中京区富小路通三条上る福長町108他","lat":35.009257,"lng":135.76456,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0471","desc":"庭を挟んだ主屋後方に西面して建つ。桁行二間半梁間三間の土蔵造二階建で、南北棟の切妻造桟瓦葺とし、正面に半間幅の下屋を設ける。外壁は鉄板張だが躯体は漆喰塗で鉢巻を廻らす。柳行李の材料となる柳の枝を収蔵した蔵で、敷地後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010484"},{"id":"00009785","register_sub_id":"101","register_pk":"195614","name":"久田家半床庵腰掛","kana":"ひさだけはんしょうあんこしかけ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区高倉通二条下る瓦町558-2他","lat":35.01282872,"lng":135.76235584,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.1㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0430","desc":"茶室の入側と、露地を挟み斜向いに建つ。木造、片流屋根、銅板葺である。軸部は丸太で構成し、南面の桔出し梁のみナグリ仕上げとする。北面壁に窓を穿ち、軒は竹垂木を疎らに配して差し出す。大振りな蹲踞などとともに豊かな露地空間を演出する腰掛である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009785"},{"id":"00009784","register_sub_id":"101","register_pk":"195613","name":"久田家半床庵茶室","kana":"ひさだけはんしょうあんちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区高倉通二条下る瓦町558-2他","lat":35.01279351,"lng":135.76229492,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺一部こけら葺及び銅板葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0429","desc":"木造平屋建、切妻造桟瓦葺で、庇等をこけら葺及び銅板葺とする。七畳広間の東に入側、北に茶室半床庵、南に玄関を配する。広間はトコなどにツラ付丸太柱を使い、半床庵は一畳と台目畳二畳、中板と一畳の点前座を用いた独創的な茶室で、三代宗全の作風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009784"},{"id":"00001776","register_sub_id":"101","register_pk":"102766","name":"百石斎（旧田邉朔郎書斎）","kana":"ひゃくせきさい（きゅうたなべさくろうしょさい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区浄土寺真如町10-2","lat":35.02261152,"lng":135.78770328,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積25㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"26 － 0066","desc":"琵琶湖疏水を計画・設計した田邉朔郎の設計による鉄筋コンクリート造２階建の書斎。内部にキングポストトラスを用いる。土蔵造風であるが，妻面に各階二つの窓を配すと共に小庇を四面に周し，採光に考慮する。ＲＣ造を得意とした田邉の堅実な作風が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001776"},{"id":"00014629","register_sub_id":"101","register_pk":"515171","name":"廣瀬家住宅主屋","kana":"ひろせけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市千歳町千歳横井97","lat":35.04897778,"lng":135.58202222,"geo_status":"db","era":"天保14年（1843）頃／明治9年頃・平成8年改修","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"26 - 0654","desc":"亀岡盆地東縁の農村にある旧家の主屋。敷地中央に南面する平屋建入母屋造平入桟瓦葺で、周囲に下屋を巡らす。内部は東を土間、西に六室を配し、南中央に式台を構える。座敷は西に床、北に棚を配した変則的な構えとする。当地域の上層農家の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014629"},{"id":"00001526","register_sub_id":"101","register_pk":"102516","name":"藤井斉成会有鄰館収蔵庫","kana":"ふじいさいせいかいゆうりんかんしゅうぞうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町44、45","lat":35.01148917,"lng":135.78117783,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"26 － 0060","desc":"第二館の北側，第一館との間に建つ。第二館の同様に，設計者は寺生元彦で，「取毀材を用いて新築」され，外壁には同じ仕様の白タイルが張られている。第二館と一体のものとして建てられ，２階には床と棚が設えられているなど上質な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001526"},{"id":"00001525","register_sub_id":"101","register_pk":"102515","name":"藤井斉成会有鄰館第二館","kana":"ふじいさいせいかいゆうりんかんだいにかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町44、45","lat":35.01126645,"lng":135.78122707,"geo_status":"db","era":"大正初期／昭和3移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、鉄板葺、建築面積250㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"26 － 0059","desc":"昭和の御大典に際し，大蔵大臣用の宿泊所として金沢市所在の横山鉱業部洋館を移築したもの。武田五一設計の第一館（京都市登録有形文化財）の背後に建つ。玄関ポーチの屋根形状や，内部のセセッション風意匠などに時代的な特色がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001525"},{"id":"00000986","register_sub_id":"101","register_pk":"101976","name":"藤田家住宅主屋","kana":"ふじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区横大路草津町25-1","lat":34.92963309,"lng":135.73582798,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積191㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"26 － 0032","desc":"桂川の左岸の旧街道沿いにある旧家で，主屋は道から少し後退して建つ。平面は，主体部が南側を広い土間とした整形６間取りで，落棟部分に１０畳大の座敷２室を付加する。土間の架構に見るべきものがある。全体的に質は高く整った外観は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000986"},{"id":"00010479","register_sub_id":"101","register_pk":"202568","name":"藤田家住宅主屋","kana":"ふじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区堀川通今出川上る西入山名町811他","lat":35.031591,"lng":135.751346,"geo_status":"db","era":"明治前期／昭和10改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階一部3階建、瓦葺、建築面積280㎡","structure_material":"木造2階一部3階建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0466","desc":"間口五間半で木瓜形の虫籠窓を穿つ東棟と同二間半の西棟からなり、西棟前面の応接間は数寄屋と洋風を融和した意匠をもつ。後方の住居部には、数寄屋または書院風の、趣を変えた座敷など多様で洗練された室を並べる。西陣の繁栄と町家の大型化を示す上質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010479"},{"id":"00010480","register_sub_id":"101","register_pk":"202518","name":"藤田家住宅茶室養心","kana":"ふじたけじゅうたくちゃしつようしん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区堀川通今出川上る西入山名町811他","lat":35.031748,"lng":135.751308,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0467","desc":"主屋の北西側に庭を介して建つ。招造桟瓦葺で南面に下屋付の切妻屋根を張出す。四畳半茶室と水屋からなり、平面形式のほか、床の前を網代天井、対面の躙口側を掛込天井とする空間構成は裏千家の茶室又隠に通ずる。京都の町家において独立した茶室を設ける好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010480"},{"id":"00000987","register_sub_id":"101","register_pk":"101977","name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区横大路草津町25-1","lat":34.9297203,"lng":135.73574985,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積25㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"26 － 0033","desc":"かつて桂川に通じた屋敷地の西寄りに建つ妻入の小規模な土蔵で，側面及び背面は竪板張りとし正面に庇が付く。小屋は登梁を用い，出入口のほか小窓を２ヶ所設けるだけの閉鎖的な構えになる。堤防側からは，主屋ともに伝統的な屋敷構えを見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000987"},{"id":"00010481","register_sub_id":"101","register_pk":"202569","name":"藤田家住宅土蔵","kana":"ふじたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区堀川通今出川上る西入山名町811他","lat":35.031735,"lng":135.75136,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0468","desc":"主屋後庭の奥に、茶室養心と並び南面して建つ。桁行梁間とも三・四メートル、土蔵造二階建、切妻造妻入り、本瓦葺で、南正面を戸口として下屋を設ける。外壁漆喰塗で鉢巻を廻らし、扉廻りなどの要所を黒漆喰塗で引締める。町家の庭園景観に趣を与える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010481"},{"id":"00010482","register_sub_id":"101","register_pk":"202519","name":"藤田家住宅門及び塀","kana":"ふじたけじゅうたくもんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区堀川通今出川上る西入山名町811他","lat":35.03153228,"lng":135.75130245,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"門 木造、間口1.6m 塀 木造、総延長6.0m","structure_material":"門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"26 － 0469","desc":"主屋東棟の南西端からのびて西棟の前庭を画す門と塀で、一連の一文字瓦を葺く。中央東寄りの門はやや奥まって構え、塀の表側は竪板張目板打、裏側は杉皮張、上部目透しとする。柱に瘤出し丸太を使い、軒も丸太で構成するなど数寄屋意匠でまとめた軽快な門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010482"},{"id":"00011344","register_sub_id":"101","register_pk":"209181","name":"藤野家住宅主屋","kana":"ふじのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区高倉通竹屋町上る坂本町707","lat":35.016489,"lng":135.762195,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"26－0508","desc":"東面して建つ。表側に茶室を兼ねた平屋建四畳半の玄関を設け、その背後に二階建居室棟を繋ぐ。南寄りには土間を通し、北寄りにダイドコ、居間、座敷を配す。二階は南北の中廊下を挟んで六畳、八畳を配す。内外とも数寄屋風意匠でまとめる大塀造町家の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011344"},{"id":"00011345","register_sub_id":"101","register_pk":"209182","name":"藤野家住宅土蔵","kana":"ふじのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区高倉通竹屋町上る坂本町707","lat":35.0165,"lng":135.762025,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"26－0509","desc":"当主の還暦を記念して建てられた土蔵。主屋の背後に中庭を介して建つ。桁行五・五メートル、梁間三・八メートルの二階建平入、本瓦葺で、庇は桟瓦葺とする。外壁は漆喰塗で、腰部はモルタル塗。南面一二階と共に正面二階にも窓を設け、中庭側の外観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011345"},{"id":"00011346","register_sub_id":"101","register_pk":"209183","name":"藤野家住宅門及び塀","kana":"ふじのけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市中京区高倉通竹屋町上る坂本町707","lat":35.01648846,"lng":135.76234258,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"門 木造、瓦葺、間口1.1m 塀 木造、瓦葺、延長28m、供待、中門及び雪隠付","structure_material":"門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"26－0510","desc":"主屋表側から両側面に矩折れに伸び、主屋玄関を囲む。南寄りに門口を開き、右に中門を設けて玄関前の庭を画す。中門脇には雪隠を、門脇には供待を備え、全体を数寄屋風にまとめる。七・七メートルの狭い間口ながら、本格的な大塀造の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011346"},{"id":"00009185","register_sub_id":"101","register_pk":"164738","name":"平安女学院有栖館主屋","kana":"へいあんじょがくいんありすかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通烏丸西入五町目町185-1他","lat":35.02027092,"lng":135.75885063,"geo_status":"db","era":"明治前期／明治24年移築改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積387㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":"26 - 0392","desc":"木造平屋建、桟瓦葺、建築面積387平方メートル、中庭を中心に玄関棟、客室棟、居室棟、廊下を配する。玄関棟は入母屋造の玄関を正面に構え、客室棟は広間2室の奥にトコ、付書院を備えた上段の間を配する。公家住宅の面影を残す明治期の官舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009185"},{"id":"00009186","register_sub_id":"101","register_pk":"164739","name":"平安女学院有栖館青天門","kana":"へいあんじょがくいんありすかんせいてんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通烏丸西入五町目町185-1他","lat":35.02020905,"lng":135.75915996,"geo_status":"db","era":"大正元年／大正12年・昭和27年移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、銅板葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":"26 -0393","desc":"敷地東側の烏丸通に面して建つ平唐門。いわゆる兜門形式になり、間口3.6メートル、銅板葺。軒を吹寄の輪垂木、扉を1枚板とし、良質なケヤキをふんだんに使用する。袖塀は桟瓦葺、壁は漆喰塗、腰を下見板張とする。優れた意匠を持つ大正期の邸宅の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009186"},{"id":"00009187","register_sub_id":"101","register_pk":"164740","name":"平安女学院有栖館長屋門","kana":"へいあんじょがくいんありすかんながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通烏丸西入五町目町185-1他","lat":35.02006153,"lng":135.75902671,"geo_status":"db","era":"明治後期／平成20年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":"26 - 0394","desc":"敷地南側の下立売通に面して建つ。木造平屋建、切妻造桟瓦葺の長屋門である。中央西側に門口を開き、東側に1室、西側に物置2室を配する。正面外壁は漆喰塗として出格子を設け、腰を下見板張とする。通りの南側の煉瓦造教会とともに、印象的な景観を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009187"},{"id":"00016406","register_sub_id":"101","register_pk":"536473","name":"Ｈｏｔｅｌ宇多野京都別墅（旧大渡家住宅）主屋","kana":"ほてるうたのきょうとべっしょ（きゅうおおわたりけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野御屋敷町14","lat":35.02492222,"lng":135.709375,"geo_status":"db","era":"昭和14年／昭和29年増築、令和6年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積520㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0705","desc":"双ヶ岡の西に位置する実業家の旧宅主屋。庭に南面する二階建の和館を中心に北東に玄関棟、西に座敷棟、南東に洋館を接続する。洋館はスペイン瓦を葺き、外壁にアーチ窓を並べたスパニッシュ様式とする。和洋の意匠を巧みに用い、大規模で良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016406"},{"id":"00016407","register_sub_id":"101","register_pk":"536474","name":"Ｈｏｔｅｌ宇多野京都別墅（旧大渡家住宅）正門","kana":"ほてるうたのきょうとべっしょ（きゅうおおわたりけじゅうたく）せいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野御屋敷町14","lat":35.02474722,"lng":135.70958889,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、間口2.8m、左右袖塀付、延長6.5m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0706","desc":"敷地東面に通りから控えて建つ腕木門で、両脇に袖塀を付す。建ちの高い切妻造桟瓦葺南北棟で、門内の腕木下に控柱を立て、主柱で棟木を受ける。門口は両開の板扉を吊り、欄間は枠状につくり、白漆喰仕上とする。大規模な屋敷の表構えを整える端正な姿の正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016407"},{"id":"00016409","register_sub_id":"101","register_pk":"536476","name":"Ｈｏｔｅｌ宇多野京都別墅（旧大渡家住宅）中門","kana":"ほてるうたのきょうとべっしょ（きゅうおおわたりけじゅうたく）ちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野御屋敷町14","lat":35.024825,"lng":135.70945833,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、間口1.2m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0708","desc":"主屋の南東、庭園の入口に開く門。切妻造桟瓦葺の東西棟で、主柱は正背面から斜材の控柱で支え、貫で固め、腕木で軒桁を支持する。軒は一軒疎垂木。主柱は強い捻れの付いた変木を用い、控柱はナグリ仕上とするなど凝ったつくりで、庭園の景観を演出する中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016409"},{"id":"00016408","register_sub_id":"101","register_pk":"536475","name":"Ｈｏｔｅｌ宇多野京都別墅（旧大渡家住宅）通用門","kana":"ほてるうたのきょうとべっしょ（きゅうおおわたりけじゅうたく）つうようもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野御屋敷町14","lat":35.02513611,"lng":135.70936111,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"26 - 0707","desc":"敷地北面の通りに開く腕木門。切妻造桟瓦葺で、門内の腕木下に控柱を立てて貫で固め、主柱で棟木を受ける。門口は引違格子戸を建て、欄間は中央に面取の長方形窓を開け、土壁仕上とする。主柱に出節丸太、控柱をナグリ仕上とするなど、瀟洒なつくりの通用門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016408"},{"id":"00004264","register_sub_id":"101","register_pk":"105254","name":"堀江家住宅主屋","kana":"ほりえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市右京区花園木辻南町15","lat":35.02078772,"lng":135.72386028,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0175","desc":"妙心寺南東の住宅地に建つ。平屋，寄棟造，桟瓦葺で，座敷飾りを備えた２室続きの座敷，玄関と寄付，茶の間と台所の各部分を，矩折れの中廊下で連絡する。台檜を用いた上質な造りで，全て和室ながら独立性を確保した間取りに近代的な郊外住宅の萌芽が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004264"},{"id":"00008726","register_sub_id":"101","register_pk":"149447","name":"堀家住宅乾蔵","kana":"ほりけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.8527616,"lng":135.77502535,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0375","desc":"主屋の西北、通り沿いに位置する。切石積基礎に建つ切妻造桟瓦葺の土蔵。桁行9.9ｍ梁間4.9ｍの平屋建。漆喰仕上げで、腰に竪板を張る。北面に桟瓦葺庇をかけ、出入口とし、引込戸をたて、南・北面に小庇付の窓を設ける。大規模な土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008726"},{"id":"00008724","register_sub_id":"101","register_pk":"149445","name":"堀家住宅主屋","kana":"ほりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85260713,"lng":135.77514259,"geo_status":"db","era":"安政6年(1859)／明治前期・昭和10年頃増築","year":1859,"year_source":"converted","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積238㎡","structure_material":"木造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0373","desc":"通りの南に占める敷地中央に北面する。桁行14ｍ梁間9.9ｍ、切妻造桟瓦葺、木造つし2階建を中心に、西面に医院棟、東面に茶室を付設する。西半部に土間、東半部に2列各3室を配する。中央に式台を設け座敷にはトコや棚を構える。近世上層農家の形式を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008724"},{"id":"00008730","register_sub_id":"101","register_pk":"149451","name":"堀家住宅長屋門","kana":"ほりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85275803,"lng":135.77513401,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0379","desc":"主屋の正面、乾蔵の東面に接して建つ。桁行7.2ｍ梁間4.0ｍ、東入母屋造とする桟瓦葺屋根。東寄りに部屋を造り、通り側に出格子窓を飾る。門は大きく両開板戸を吊り、乾蔵寄りに潜りを設ける。乾蔵とともに重厚な表構えをなし、庄屋らしい風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008730"},{"id":"00008725","register_sub_id":"101","register_pk":"149446","name":"堀家住宅離れ座敷","kana":"ほりけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85246253,"lng":135.77529021,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"converted","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0374","desc":"主屋の東南に東西棟で建つ。桁行11ｍ梁間5.8ｍの木造平屋建、入母屋造桟瓦葺。12畳半と8畳からなり、北・西面に縁をまわす。主室の東面にトコや付書院などを構える。トコに皮付丸太、鉄刀木を用い、小壁を扇形に穿つなど数寄屋風意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008725"},{"id":"00008728","register_sub_id":"101","register_pk":"149449","name":"堀家住宅東蔵","kana":"ほりけじゅうたくひがしくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85257778,"lng":135.77533909,"geo_status":"db","era":"明治8年／明治前期増築","year":1875,"year_source":"converted","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積42㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0377","desc":"主屋の東から渡り廊下を介して続く。南北棟とする切妻造本瓦葺。鬼に殺生釘を付ける。桁行5.9ｍ梁間4.9ｍの土蔵造2階建。切石積基礎とし、漆喰仕上げで腰に竪板を張る。西面を正面とし、掛子塗の両開戸を吊り、上部に文字を鏝細工で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008728"},{"id":"00008727","register_sub_id":"101","register_pk":"149448","name":"堀家住宅古蔵","kana":"ほりけじゅうたくふるぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85270548,"lng":135.7749909,"geo_status":"db","era":"弘化2年(1845)","year":1845,"year_source":"converted","year_min":1845,"year_max":1845,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0376","desc":"乾蔵の南西に南北棟で建つ。桁行6.0ｍ梁間4.0ｍの土蔵造二階建。切妻造桟瓦葺。切石積基礎とし、外壁は漆喰仕上げで、腰に竪板を張る。西面に出入口を設け、瓦庇を付ける。内部は板敷で、壁を土壁、小屋を登梁とし、垂木を配る。古風な雰囲気を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008727"},{"id":"00008729","register_sub_id":"101","register_pk":"149450","name":"堀家住宅南蔵及び南蔵座敷","kana":"ほりけじゅうたくみなみくらおよびみなみくらざしき","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府城陽市寺田中大小67-1","lat":34.85245955,"lng":135.77513535,"geo_status":"db","era":"明治中期／昭和前期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"26 － 0378","desc":"主屋南に建つ土蔵で、西に木造平屋建の座敷を付設する。南蔵は桁行5.9ｍ梁間6.0ｍの土蔵造2階建、切妻造桟瓦葺。外壁は漆喰仕上げ。座敷は桁行6.2ｍ梁間6.0ｍ、切妻造桟瓦葺。蔵側に納屋、西に八畳間を配する。離れの生垣とともに敷地北辺を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008729"},{"id":"00012382","register_sub_id":"101","register_pk":"531706","name":"岐美家住宅主屋","kana":"みちよしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山西大野町26他","lat":35.04235278,"lng":135.75355278,"geo_status":"db","era":"昭和8年頃／昭和40年頃改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"26-566","desc":"閑静な住宅地に南面して建つ。玄関妻壁に中世風蟇股と舟肘木を飾り、東側の張出しを洋間とし、西側に座敷を雁行に配して廊下を廻らせる。柱仕上や天井等の仕様を部屋ごとに変え、数寄屋風や書院風の意匠に濃淡をつける、瀟洒で上質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012382"},{"id":"00012384","register_sub_id":"101","register_pk":"531708","name":"岐美家住宅土蔵","kana":"みちよしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山西大野町26他","lat":35.04246111,"lng":135.75347222,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"26-568","desc":"主屋後方、離れの西端に接続して東西棟で建つ。土蔵造二階建、桁行3･9メートル梁間3･9メートル、切妻造桟瓦葺で、各階とも離れから出入りする。軒に鉢巻を廻らし、南面上下階の窓庇に漆喰塗の繰形付持送を付す。屋敷構えを構成する丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012384"},{"id":"00012383","register_sub_id":"101","register_pk":"531707","name":"岐美家住宅離れ","kana":"みちよしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山西大野町26他","lat":35.04246667,"lng":135.75353333,"geo_status":"db","era":"昭和8年頃／昭和40年頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"26-567","desc":"主屋背面の庭を挟んで東西棟で建ち、西端の渡廊下で主屋と連絡する。南面は開口を広くとり、軒は丸太垂木を配る。一階は茶室と六畳を東西に並べ、茶室は四畳半台目で蒲天井を張り、床柱に皮付の曲り材、床框に割竹を使う。数寄屋を基調とした上質な離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012383"},{"id":"00012385","register_sub_id":"101","register_pk":"531709","name":"岐美家住宅門","kana":"みちよしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山西大野町26他","lat":35.04228333,"lng":135.75363056,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"26-569","desc":"敷地南辺東寄りに開く。切妻造桟瓦葺、間口1･8メートルの腕木門で、左右に袖塀を付ける。軸部から軒まで磨き丸太で構成し、門口に引違いの格子戸、欄間に細丸竹を吹寄せに入れ、軒は吹寄せ疎垂木とする。袖塀は腰高に竪板を張る。端正で気品を備えた正門","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012385"},{"id":"00000796","register_sub_id":"101","register_pk":"101786","name":"密語菴","kana":"みつごあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市左京区若王寺町67","lat":35.23592218,"lng":135.79285722,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺一部銅板葺，建築面積179㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0023","desc":"若王寺神社境内に隣接する広大な敷地に南面して建つ，上質の瀟洒な数寄屋造の住宅。中央に玄関部を置き西側に居住部分，東側に茶室や客室を配する構成になる。原三渓の番頭古郷時侍の旧宅で，後和辻哲郎や岡崎桃乞が居住，現在は哲学者梅原猛の居宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000796"},{"id":"00009509","register_sub_id":"101","register_pk":"194302","name":"宮本家住宅主屋","kana":"みやもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町27-13","lat":35.03792784,"lng":135.74303788,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"26 － 0413","desc":"船岡山南麓に南面し、木造二階建、建築面積九三平方メートル、入母屋造桟瓦葺で正面に切妻の玄関を張出す。平面は中廊下式で玄関東脇に洋風の応接間を配し、廊下西側と二階には数寄屋風で瀟洒なつくりの和室を並べる。唐木屋工務店が手がけた良質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009509"},{"id":"00009510","register_sub_id":"101","register_pk":"194303","name":"宮本家住宅門","kana":"みやもとけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町27-13","lat":35.03780649,"lng":135.74306501,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造、間口1.9m","structure_material":"コンクリート造","registered":"2013.03.29(平成25.03.29)","register_no":"26 － 0414","desc":"敷地南面東寄りに位置し、主屋へ向けて斜上する通路の入口となる。高さ一・八メートルのコンクリート造門柱一対を間口一・九メートルに立て、表面に黄茶色で粗面仕上げの施釉タイルを貼り、頂部に八角錐形の灯具を載せる。昭和初期の住宅地景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009510"},{"id":"00004366","register_sub_id":"101","register_pk":"105356","name":"武者小路千家主屋","kana":"むしゃのこうじせんけしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区武者小路通新町西入西無車小路町613-2他","lat":35.02789984,"lng":135.75484182,"geo_status":"db","era":"明治14頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"26 － 0182","desc":"木造２階建，桟瓦葺の瀟洒な数寄屋住宅で，表門から路地を経て玄関に至る。居室の周囲に４畳桝床の半宝庵，７畳広間の環翠園（矢倉家広間を移築），３畳台目の行舟亭の３茶室と千利休像を祀る祖堂を配した茶家ならではの構成をもつ。大工棟梁は平井儀助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004366"},{"id":"00004367","register_sub_id":"101","register_pk":"105357","name":"武者小路千家茶室官休庵","kana":"むしゃのこうじせんけちゃしつかんきゅうあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市上京区武者小路通新町西入西無車小路町613-2他","lat":35.02800193,"lng":135.75490765,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺一部こけら葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"26 － 0183","desc":"主屋の北付属棟の東に接続する。武者小路千家の初代一翁好みの茶室として再建。１畳の客座と台目の点前座との間に５寸２分幅の半板を入れた独特の平面で，東に二つの下地窓，南に躙口と下地窓を開き，北に水屋が続く。屋根は桟瓦葺で螻羽と軒をこけら葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004367"},{"id":"00004368","register_sub_id":"101","register_pk":"105358","name":"武者小路千家茶室弘道庵","kana":"むしゃのこうじせんけちゃしつこうどうあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区武者小路通新町西入西無車小路町613-2他","lat":35.02790634,"lng":135.75499471,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"26 － 0184","desc":"武者小路千家の九代愈好斎が再建した稽古の間。庭を挟んで主屋東に建つ。木造平屋建，屋根は桟瓦葺で軒を銅板葺とする。南側道路からやや引込んで玄関の土間，寄付６畳，次の間６畳半が並ぶ。１５畳広間の弘道庵には床と附書院を設け，土縁を巡らせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004368"},{"id":"00004369","register_sub_id":"101","register_pk":"105359","name":"武者小路千家土蔵","kana":"むしゃのこうじせんけどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区武者小路通新町西入西無車小路町613-2他","lat":35.02801382,"lng":135.75480906,"geo_status":"db","era":"明治14頃","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"26 － 0185","desc":"敷地の西辺に位置し，主屋の北に接続する。桁行３間梁間２間半の土蔵造平屋建で，屋根は切妻造，本瓦葺で，外壁を白漆喰仕上げとする。主屋から北へ延びる廊下に蔵前を設け，両開きの土戸，裏白戸，網戸を建て込む。西面に円形の小窓二つを開けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004369"},{"id":"00009646","register_sub_id":"101","register_pk":"194642","name":"室賀家住宅主屋","kana":"むろがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市山科区小山北林町36-5","lat":34.98685259,"lng":135.83412126,"geo_status":"db","era":"昭和13／昭和40頃増築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"26 － 0425","desc":"木造二階建、切妻造桟瓦葺で、北正面は玄関前に出桁の深い軒を出し、二階は虫籠窓風の縦格子窓とする。内部は洋風の居間と食堂を中心に西に中廊下を延ばして和室を配し、座敷南側はサンルーム風の広縁とする。民家の意匠をたくみに取入れた近代住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009646"},{"id":"00010983","register_sub_id":"101","register_pk":"208953","name":"室田家住宅主屋","kana":"むろたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区上高野大明神町5","lat":35.064915,"lng":135.796023,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"26-0498","desc":"市街北東の近郊農村の敷地で南面する。切妻造桟瓦葺で煙出しを載せ、正背面に下屋を通し、つし部に虫籠窓を並べる。床上部は四間取系の五室で座敷造作も洗練され、広い土間にウマヤと勾玉形の七口竈を築く。京都近郊の町家風意匠も備えた農家建築となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010983"},{"id":"00004261","register_sub_id":"101","register_pk":"105251","name":"茂庵（旧谷川茂次郎茶苑）田舎席","kana":"もあん（きゅうたにがわしげじろうちゃえん）いなかせき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田神楽岡町7-2他","lat":35.025658,"lng":135.787064,"geo_status":"db","era":"大正末期～昭和初期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1945,"year_label":"大正末期～昭和初期","structure":"木造平屋建、銅板葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0172","desc":"６畳の茶席を中心に，４畳半の前室，水屋，台所，風呂場等からなる。茶席は躙口を構え東面北端の壁に織部板を付し壁床を設け，東端半間を垂れ壁で区切り，北半間を網代天井，南１間を化粧屋根裏とする。東に如意ヶ岳を望む開放的な構えで随所に創意が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004261"},{"id":"00004260","register_sub_id":"101","register_pk":"105250","name":"茂庵（旧谷川茂次郎茶苑）旧点心席","kana":"もあん（きゅうたにがわしげじろうちゃえん）きゅうてんしんせき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田神楽岡町7-2他","lat":35.02631919,"lng":135.787109,"geo_status":"db","era":"大正末期～昭和初期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1945,"year_label":"大正末期～昭和初期","structure":"木造2階建、銅板葺、建築面積64㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0171","desc":"数寄者谷川茂庵が営んだ吉田山荘の独立して建つ食堂で，２階建，寄棟造，銅板葺で基壇上に建つ。軸部，小屋組等全体に丸太で構成され，東側面１階は壁面を後退させ懸造のようにみせる。棟両端に鳥形の鬼瓦をのせるなど，趣味性の強い，かつ優れた意匠の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004260"},{"id":"00004262","register_sub_id":"101","register_pk":"105252","name":"茂庵（旧谷川茂次郎茶苑）静閑亭","kana":"もあん（きゅうたにがわしげじろうちゃえん）せいかんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田神楽岡町7-2他","lat":35.02610219,"lng":135.78721088,"geo_status":"db","era":"大正末期～昭和初期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1945,"year_label":"大正末期～昭和初期","structure":"木造地上1階一部地下1階建、銅板葺、建築面積30㎡","structure_material":"木造地上1階一部地下1階建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0173","desc":"主室の他水屋，玄関，便所を付し，斜面に建ち東側は懸造になる。主室は曲木を巧みに組み合わせた梁組をみせ，西面に大床と脇に火灯形に刳った平書院風の窓を開ける。当初は床を張らない立礼の席で，装飾タイル張りの地下室を備えるなど，独創的な構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004262"},{"id":"00004263","register_sub_id":"101","register_pk":"105253","name":"茂庵（旧谷川茂次郎茶苑）待合","kana":"もあん（きゅうたにがわしげじろうちゃえん）まちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田神楽岡町7-2他","lat":35.02634277,"lng":135.78733586,"geo_status":"db","era":"大正末期～昭和初期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1945,"year_label":"大正末期～昭和初期","structure":"木造平屋建、銅板葺、建築面積9㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"26 － 0174","desc":"山頂付近にあった本席に付属する供待。内部は南西に１畳半大の腰掛を設け，床はモルタル塗で四半敷状の目地を切り，曲木による変化に富んだ梁組をみせる。小規模で簡素ながら，軒の深い緩勾配の寄棟屋根による外観や丸太を多用した造作など，雅趣に富む建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004263"},{"id":"00015327","register_sub_id":"101","register_pk":"532451","name":"柳町会議所（旧馬場家住宅主屋）","kana":"やなぎまちかいぎしょ（きゅうばばけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府亀岡市柳町14-1","lat":35.00978056,"lng":135.57889167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0688","desc":"柳町通りと南北の通りが交差する角地に建つ茶の宗匠の旧主屋。つし二階建切妻造平入桟瓦葺で、二階に二箇所の虫籠窓を開ける。土間にチャノマを張出す特異な平面で座敷は前板を設けた整った床構え。建ちの低い古めかしい外観で地域の歴史的景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015327"},{"id":"00004594","register_sub_id":"101","register_pk":"105584","name":"家邊徳時計店（家邊家住宅）主屋","kana":"やべとくとけいてん（やべけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区三条通富小路東入中之町25","lat":35.00843086,"lng":135.76527162,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積129㎡","structure_material":"木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0194","desc":"店舗後方に建つ居住棟。８畳の座敷がある２階建を中心に，店舗との接続部には平屋建の玄関があり，背後にも平屋建の茶の間や離れを附属する。真壁造，桟瓦葺，端正なつくりの和風建築で，効果的に中庭や坪庭を用いた平面構成になり，京の町家の伝統が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004594"},{"id":"00001432","register_sub_id":"101","register_pk":"102422","name":"山口家住宅座敷棟","kana":"やまぐちけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市西京区山田上ノ町26","lat":34.98746969,"lng":135.687927,"geo_status":"db","era":"大正期～昭和初期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1945,"year_label":"大正期～昭和初期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0055","desc":"主屋の式台の間の上手に接続し，主屋との間に中庭を挟んで座敷，仏間，次の間，茶室などを配す。大正から昭和初期の和風書院建築で，昭和４０年頃に現在地に移築したものである。良質で洗練された意匠を持ち，主屋とも調和して一体の趣をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001432"},{"id":"00001431","register_sub_id":"101","register_pk":"102421","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市西京区山田上ノ町26","lat":34.98753304,"lng":135.68793183,"geo_status":"db","era":"江戸末期～明治初期","year":1856,"year_source":"estimated","year_min":1830,"year_max":1882,"year_label":"江戸末期～明治初期","structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0054","desc":"代々庄屋を営んでいた旧家の主屋。つし二階建て，切妻造の中央部の周囲に庇を廻した形式で，桟瓦葺とする。囲炉裏や竈が残る広い土間に沿って一列に居室を並べる。最前の一室は土間から入る玄関の間とし，その上手に式台の間が張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001431"},{"id":"00001433","register_sub_id":"101","register_pk":"102423","name":"山口家住宅長屋門","kana":"やまぐちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市西京区山田上ノ町26","lat":34.98752842,"lng":135.68815052,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積66㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0056","desc":"入母屋造，茅葺の大型の長屋門で，東面する。背面北半部と北側面に桟瓦葺の庇が張り出す。入口に両開きの板扉と脇戸を設け，右手外壁面に横連子窓を構える。旧家の表門としての豪壮で風格のある構えを良く伝えており，歴史的な街路景観を引き立たせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001433"},{"id":"00008144","register_sub_id":"101","register_pk":"132585","name":"山田家住宅主屋","kana":"やまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町東一口35","lat":34.90419585,"lng":135.73992745,"geo_status":"db","era":"江戸後期／昭和23年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0345","desc":"敷地の中央に北面して建つ。桁行１９ｍ梁間１２ｍ、切妻造桟瓦葺で、四周に下屋をめぐらし、正面中央に入母屋屋根の玄関を構える。内部は西寄りに土間、東側に六間取を設け、ザシキの座敷飾りや彫刻欄間などに意匠を凝らす。上質なつくりになる近世民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008144"},{"id":"00008146","register_sub_id":"101","register_pk":"132587","name":"山田家住宅長塀","kana":"やまだけじゅうたくながべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町東一口35","lat":34.90430175,"lng":135.74009648,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、延長20m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0347","desc":"長屋門の東端から敷地北東辺沿いに延び、折曲り延長２０ｍを測る。長屋門と一連の切石積石垣上に建ち、切妻造本瓦葺で、外壁は、長屋門と同様に腰を簓子下見板張とし、軒は腕木とも漆喰で塗り込める。旧家に相応しい格式ある屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008146"},{"id":"00008145","register_sub_id":"101","register_pk":"132586","name":"山田家住宅長屋門","kana":"やまだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町東一口35","lat":34.90430989,"lng":135.73994375,"geo_status":"db","era":"江戸後期／大正7年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0346","desc":"敷地北辺の石垣上に建ち、桁行２７ｍ梁間４．０ｍ、入母屋造本瓦葺である。東寄りに門口を開き、その東西に居室や物入などを配する。外壁は武者窓や与力窓を構え、腰を簓子下見板張とし、軒は出桁造で漆喰塗とする。重厚な表構えをつくる大型の長屋門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008145"},{"id":"00006542","register_sub_id":"101","register_pk":"107525","name":"山中油店戌亥蔵","kana":"やまなかあぶらてんいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区下立売通智恵光院西入下丸屋町508","lat":35.020378,"lng":135.74580726,"geo_status":"db","era":"文政期／昭和2改修","year":1824,"year_source":"estimated","year_min":1818,"year_max":1830,"year_label":"文政期","structure":"土蔵造平屋建、瓦葺、建築面積62㎡","structure_material":"土蔵造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0260","desc":"敷地の北西隅に建つ土蔵造平屋建。桁行６間半，梁間２間半の東西棟で，切妻造，桟瓦葺とする。内部を２室に分け，それぞれ南面に両開塗戸の戸口を設け，東室には２階床を張る。小屋組は梁を二重にかけ，束立とする。外壁は白漆喰塗で，腰の焼板張が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006542"},{"id":"00006541","register_sub_id":"101","register_pk":"107524","name":"山中油店辰巳蔵","kana":"やまなかあぶらてんたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通智恵光院西入下丸屋町508","lat":35.02016935,"lng":135.74613031,"geo_status":"db","era":"明治33／昭和46曳家","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0259","desc":"敷地の南東隅，主屋の東に建つ土蔵造平屋建。桁行４間半，梁間３間の南北棟で，切妻造，桟瓦葺とする。戸口は西面に設け，鉄板葺庇を付ける。外壁は白漆喰塗で，腰を縦羽目板張とする。小屋組は地棟に登梁を架ける。通りから庭越しに見せる妻壁が美しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006541"},{"id":"00006143","register_sub_id":"101","register_pk":"107127","name":"山本家住宅勝手門及び塀","kana":"やまもとけじゅうたくかってもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区中立売通西洞院東入三丁町446他","lat":35.02510352,"lng":135.75440083,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"勝手門 木造、瓦葺、間口1.5m、塀 木造、瓦葺、延長28m、便所付","structure_material":"勝手門 木造","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0241","desc":"勝手門は敷地西面中央に建ち，木造の間口１間の腕木門の形式で，引違格子戸を入れる。両端に屋根付の塀を延ばし，北端に便所を設ける。南側の塀は敷地南西角を周り，正門まで延び，基礎を切石とし，腰板付，目板瓦葺で，欄間を付ける。落ち着いた気品ある外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006143"},{"id":"00006209","register_sub_id":"101","register_pk":"107193","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区中立売通西洞院東入三丁町446他","lat":35.025181,"lng":135.754532,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0238","desc":"南西角地の敷地中央に建つ。桁行９間，梁間５間半の規模で，木造２階建，入母屋造，桟瓦葺とする。南東隅に洋間応接室を設け，脇に玄関を設け，廊下で各室を結ぶ。１・２階共に東側の庭に面して続き間座敷を設ける。意匠，規模共に近代和風住宅として優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006209"},{"id":"00006211","register_sub_id":"101","register_pk":"107195","name":"山本家住宅正門及び塀","kana":"やまもとけじゅうたくせいもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区中立売通西洞院東入三丁町446他","lat":35.02507346,"lng":135.75457257,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"正門 木造、瓦葺、間口1.8m、塀 木造、瓦葺、延長19m","structure_material":"正門 木造","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0240","desc":"敷地南側の正面に建ち，正門は間口一間の木造で切妻造，桟瓦葺とし，両引格子戸を入れ，袖壁を付け，正面東西に高塀を設ける。高塀は腰板上部を中塗仕上げとし，目板瓦葺とする。高塀西端より主屋玄関まで庭塀を延ばす。敷地正面の落ち着きある景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006211"},{"id":"00006210","register_sub_id":"101","register_pk":"107194","name":"山本家住宅土蔵","kana":"やまもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区中立売通西洞院東入三丁町446他","lat":35.02527214,"lng":135.75443762,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0239","desc":"敷地北西隅に南北棟で建つ。桁行２間半，梁間２間で，土蔵造２階建，切妻造，桟瓦葺とする。２階両妻側に庇付窓を開き，１階東平面に戸口を開く。掛子塗の扉内側及び楣部を黒漆喰塗とし，外壁及び鉢巻を漆喰塗，腰を縦板張とし，整った外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006210"},{"id":"00014492","register_sub_id":"101","register_pk":"513906","name":"吉岡家住宅主屋","kana":"よしおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府木津川市加茂町尻枝縄手87","lat":34.73420278,"lng":135.88438611,"geo_status":"db","era":"江戸後期／明治17年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"26 - 0651","desc":"岩船寺から北麓の農村にある旧家の主屋。座敷側入母屋造、土間側落棟とする大和棟の茅葺民家。床上は六間取で、表に６畳３室の続き間座敷、裏は大小３室を並べる。大戸口脇と土間にイモグラを設け、七連竈は見応えがある。差鴨居を突止め溝にして古式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014492"},{"id":"00009991","register_sub_id":"101","register_pk":"196138","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区新町通六角下る六角町363他","lat":35.00657497,"lng":135.75649645,"geo_status":"db","era":"明治後期／昭和10改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0447","desc":"通りに東面して構える表屋は、上下階とも出桁造で、一階南寄りを土間の戸口とし、北寄りに出格子をたてて中央に揚げ見世を設える。二階は両端の半間を除き平格子とする。玄関奥の居住部は田字形四間取である。内外ともに良質な意匠になる、表屋造の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009991"},{"id":"00009325","register_sub_id":"101","register_pk":"194118","name":"吉田山荘（旧東伏見家住宅）表門","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02255588,"lng":135.78673056,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、間口3.9m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0398","desc":"敷地東辺南寄りに開、一間一戸平唐門、銅板葺である。門口は三・九メートルで柱間に板戸を吊り、円柱上に女梁と男梁、桁行中央にも男梁を置いて蟇股と舟肘木で棟木を受ける。左右の土塀は漆喰塗で下部はモルタル洗出し。優美で格調のある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009325"},{"id":"00009328","register_sub_id":"101","register_pk":"194121","name":"吉田山荘（旧東伏見家住宅）北蔵","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）きたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02299929,"lng":135.78658958,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0401","desc":"敷地西北部に南北棟で建つ。桁行五・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺。東面中央の戸口前の廊下が本館主屋の西面に接続する。外壁は白漆喰塗で腰に水切を廻し、二階北面に窓を開く。小屋組は登梁である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009328"},{"id":"00009327","register_sub_id":"101","register_pk":"194120","name":"吉田山荘（旧東伏見家住宅）旧車庫","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）きゅうしゃこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02287758,"lng":135.78690307,"geo_status":"db","era":"昭和7年頃／平成20年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0400","desc":"敷地東北部に建ち、桁行七・四メートル梁間六メートル、木造二階建フランス瓦葺で、腰折屋根両面にドーマー窓を切上げて上階に採光する。外壁はモルタル塗で腰をモルタル洗出しとする。旧は西妻から車両を入れていた。和風の建物群と対照的な洋風建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009327"},{"id":"00009326","register_sub_id":"101","register_pk":"194119","name":"吉田山荘（旧東伏見家住宅）旧門番所","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）きゅうもんばんじょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02250139,"lng":135.78669344,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0399","desc":"表門の南側に建ち、桁行四メートル梁間三メートル、木造平家建、入母屋造桟瓦葺である。東道路側は石積基壇上に建ち、外壁は漆喰塗で腰を竪板張とし、西面に戸口を設け、東面窓に格子を建てる。柱上に舟肘木を置き、軒は疎垂木で軽快な意匠の建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009326"},{"id":"00009324","register_sub_id":"101","register_pk":"194117","name":"吉田山荘（旧東伏見家住宅）本館","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）ほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02283761,"lng":135.78666679,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積237㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0397","desc":"吉田山南麓に建つ木造二階建、建築面積二三七平方メートル、入母屋造桟瓦葺で、東を玄関とし、中廊下の南に居室を配し、南西を平屋の離れとする。和室を主とするが、ステンドグラスや二階東面のベランダなどに洋風意匠を加味した、良質な近代和風邸宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009324"},{"id":"00009329","register_sub_id":"101","register_pk":"194122","name":"吉田山荘（旧東伏見家住宅）南蔵","kana":"よしださんそう（きゅうひがしふしみけじゅうたく）みなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田下大路町59-1他","lat":35.02295527,"lng":135.78654056,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0402","desc":"北蔵の南に南北棟で並び、桁行四・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺である。北蔵東から延びる廊下で本館に接続する。外壁は白漆喰塗で腰に水切を廻し、足元をモルタル洗出しとし、二階南面に窓を開く。小屋組は束立とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009329"},{"id":"00011731","register_sub_id":"101","register_pk":"210747","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ケ崎雲路町6","lat":35.051971,"lng":135.782896,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"26-0520","desc":"通りに北面し、多数の入母屋屋根を複層させた外観を持つ。玄関ホールを兼ねた広い廊下を中心に、北東に数寄屋意匠を加味した客間をおき、南側に家族向けの広間や食堂を洋間として配置する。家族のための部屋配置を重視する近代的な住宅思潮を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011731"},{"id":"00006203","register_sub_id":"101","register_pk":"107187","name":"樂家住宅衣装蔵","kana":"らくけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.02587107,"lng":135.753204,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0230","desc":"主屋と本蔵の間に東西棟で建つ。桁行２間，梁間１間半で，土蔵造２階建，切妻造，本瓦葺とし，南側に６畳間の蔵前を設け，主屋と連絡する。２階南側に瓦庇付の窓を開く。扉は掛子塗とし，扉裏及び楣部を黒漆喰塗とする。小規模ではあるが重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006203"},{"id":"00006208","register_sub_id":"101","register_pk":"107192","name":"樂家住宅表門","kana":"らくけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.025757,"lng":135.753479,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口4.5m、中門及び塀・便所及び手洗い付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0237","desc":"東側通りに面して建つ表門である。間口４．５ｍで，中央に引違いの格子戸を開き，内側に片引きの板戸を建て込む。木造で門両側に腰板付の土壁を立ち上げ，全体に切妻造，桟瓦葺の屋根を架ける。敷地側に便所及び手洗いを設け，主屋まで中門及び塀を伸ばす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006208"},{"id":"00006204","register_sub_id":"101","register_pk":"107188","name":"樂家住宅窯場","kana":"らくけじゅうたくかまば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.025829,"lng":135.753113,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積28㎡、黒樂窯及び赤樂窯付","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0232","desc":"本蔵の南西に接して建つ。桁行３間，梁間２間の規模で，入母屋造（北は切妻造），桟瓦葺とし，内部の壁及び天井裏を土塗とする。内部北西に薪窯の赤樂窯を置き，上方に煙出しを上げる。東方に小振りの本窯の黒樂窯を設ける。貴重な窯を備えた陶芸施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006204"},{"id":"00006207","register_sub_id":"101","register_pk":"107191","name":"樂家住宅腰掛待合","kana":"らくけじゅうたくこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.025826,"lng":135.753464,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積4.6㎡、塀延長10m付","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0235","desc":"通りに面して表門の北側に建つ。桁行１間，梁間半間の規模で，西側に腰掛を設け，通り側に出格子窓を付け，南側に雪隠を設け，全体に切妻造，桟瓦葺の屋根を架ける。また，南北に延長１０ｍの塀を設ける。落ち着きのある和風意匠の外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006207"},{"id":"00006163","register_sub_id":"101","register_pk":"107147","name":"樂家住宅主屋","kana":"らくけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.025764,"lng":135.753326,"geo_status":"db","era":"明治前期／平成18増改築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積263㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0229","desc":"敷地中央，やや東通りに寄って建つ。桁行１１間，梁間７間の規模で，木造２階建，切妻造，桟瓦葺とする。南東隅に玄関を設け，座敷４室を設ける。南西隅に台所を配し，南側に通り土間を設ける。外観は町家風であるが内部は意匠を凝らした数寄屋普請とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006163"},{"id":"00006205","register_sub_id":"101","register_pk":"107189","name":"樂家住宅土小屋","kana":"らくけじゅうたくつちごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.02587352,"lng":135.75306772,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、スレート葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0233","desc":"敷地北西隅に建つ作陶用の土の保管小屋である。桁行２間半，梁間１間半で，木造平屋建，切妻造，スレート葺とする。基礎を煉瓦造とし，土の保管場と土突き場を設ける。小規模で簡素な建物ではあるが，作陶にとって貴重な建物で，陶芸施設の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006205"},{"id":"00006206","register_sub_id":"101","register_pk":"107190","name":"樂家住宅供待","kana":"らくけじゅうたくともまち","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.02568804,"lng":135.753464,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積3.0㎡、塀延長7.0m付","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0236","desc":"通りに面して表門の南側に建つ。桁行１間，梁間１．５尺の規模で，腰掛を設け，通り側に４尺幅の出格子窓を付け，切妻造，桟瓦葺の屋根をかける。また，西側敷地境に長さ７ｍの瓦屋根付の木造の塀を付ける。敷地南東隅の和風意匠の外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006206"},{"id":"00006202","register_sub_id":"101","register_pk":"107186","name":"樂家住宅本蔵","kana":"らくけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.025852,"lng":135.753143,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0231","desc":"主屋の北西方，敷地境に近接して南北棟で建つ。桁行２間半，梁間２間で，土蔵造２階建，切妻造，本瓦葺とする。東側に庇を張り出して戸口を開き，２階平側に窓を設け，外壁を漆喰塗とする。庇部北端に南向きに稲荷社を設ける。小規模ではあるが重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006202"},{"id":"00009995","register_sub_id":"101","register_pk":"196142","name":"落柿舎","kana":"らくししゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨小倉山緋明神町20","lat":35.02050932,"lng":135.67087972,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺一部瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0451","desc":"嵯峨小倉山の敷地中央に南面して建ち、寄棟造茅葺である。東端を狭い土間とし、床上部は西端南側を四畳半の主室として西面にトコとトコ脇を備え、他は二畳と三畳を配する。数寄屋を基調とする穏やかな佇まいの茅舎で、嵯峨の風情を醸す重要要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009995"},{"id":"00000220","register_sub_id":"101","register_pk":"101210","name":"楽々荘玄関","kana":"らくらくそうげんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市北町44","lat":35.01587924,"lng":135.57645359,"geo_status":"db","era":"明治31頃","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積83㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"26 － 0005","desc":"洋館の南西側にあり、廊下を介して和館に通じる。式台を備えた本格的な和風の玄関だが、入母屋造の妻を小さくおさえる等、全体のバランスに配慮したつくりとなっている。設計を手がけた作者の技能の水準の高さをよく示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000220"},{"id":"00000219","register_sub_id":"101","register_pk":"101209","name":"楽々荘日本館","kana":"らくらくそうにほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市北町44","lat":35.01605024,"lng":135.57657024,"geo_status":"db","era":"明治31頃","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積235㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"26 － 0004","desc":"和館部は、当初は主人室、夫人室として使用されていたと伝える。平屋建だが、屋根は庇屋根を廻し二重とする。主人室・夫人室の室内意匠を変えており、とくに両室のトコ㎡棚の構成や用いられた材料の扱い等に技術㎡技能の水準の高さを見ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000219"},{"id":"00000218","register_sub_id":"101","register_pk":"101208","name":"楽々荘洋館","kana":"らくらくそうようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市北町44","lat":35.01600965,"lng":135.57659396,"geo_status":"db","era":"明治31頃","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造一部木造2階建，瓦葺，建築面積103㎡","structure_material":"煉瓦造一部木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"26 － 0003","desc":"衆議院議員・貴族院議員をつとめた田中源太郎の住宅として建設されたもので、設計施工は清水組である。東と南にベランダを持つ外観に特徴があり、内部の各室の床や暖炉の仕様を変える等、各部に用いられた技能の水準が高い手の込んだつくりの建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000218"},{"id":"00004992","register_sub_id":"101","register_pk":"105982","name":"レストラン・ノアノア（旧橋本関雪邸洋館）","kana":"れすとらん・のあのあ（きゅうはしもとかんせつていようかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区浄土寺石橋町35-1","lat":35.02718617,"lng":135.79312568,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積63㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0201","desc":"吉田山東方を南北に流れる白川沿いの敷地に北面して建つ。ＲＣ造２階建で，外装モルタル塗とする。スパニッシュ様式を基調としつつも，玄関の庇に垂木形をつくり出すなど和風を加味し，昭和初期の洋風住宅デザインの一つの潮流を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004992"},{"id":"00006869","register_sub_id":"101","register_pk":"107851","name":"和田家住宅主屋","kana":"わだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通花屋町下る東若松町832他","lat":34.99268841,"lng":135.75682338,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0277","desc":"新町通に西面して建つ。桁行４間梁間２間の表屋の背後に、坪庭・玄関を介して、切妻屋根の台所と片流屋根の座敷を配する。新町通側の外観は、１階の北側を出格子、南側を荒格子とし、つし２階には切子格子を嵌めた伝統的な京町家の表構えを保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006869"},{"id":"00006870","register_sub_id":"101","register_pk":"107852","name":"和田家住宅土蔵","kana":"わだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区新町通花屋町下る東若松町832他","lat":34.99269489,"lng":135.75706818,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0278","desc":"主屋の東方、敷地の東奥に位置し、南北棟で建つ。桁行２間梁間２間規模、切妻造本瓦葺、平入の２階建土蔵で、西面に土庇を差し出して戸口を設け、２階に小窓を開ける。窓の引戸の墨書「伊勢屋義兵衛 酉六月」から明治２５年の和田家取得以前の状況が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006870"},{"id":"00000798","register_sub_id":"101","register_pk":"101788","name":"渡邊家住宅什器蔵","kana":"わたなべけじゅうたくじゅうきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府舞鶴市字竹屋101","lat":35.4507022,"lng":135.32648006,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積22㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0025","desc":"敷地の奥側に建つ小規模な白漆喰塗の土蔵で，切妻造の東西棟とし東面に引き戸を開いて出入口とする。家蔵の什器類を納めたことから，その名が付けられた。建築年代は，明治３年の記のある祈祷札があり，様式的にもその頃のものと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000798"},{"id":"00000797","register_sub_id":"101","register_pk":"101787","name":"渡邊家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府舞鶴市字竹屋101","lat":35.45063324,"lng":135.32670121,"geo_status":"db","era":"明治3頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造２階建，瓦葺，建築面積142㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0024","desc":"渡邊家は近世末期に回船問屋を務めた旧家で，高野川を背に南北に続く竹屋町にある。主屋は大型の町家で，正面が近代商家風に改造されたが伝統的な町並みを形成している。土間部は豪壮な架構をみせ，居室部は欄間など優れた意匠になる良質の居宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000797"},{"id":"00000799","register_sub_id":"101","register_pk":"101789","name":"渡邊家住宅新蔵","kana":"わたなべけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府舞鶴市字竹屋101","lat":35.45068538,"lng":135.32641364,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積45㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0026","desc":"高野川の河岸に平を見せて建つ切妻造，平入の２階建土蔵。煉瓦造の高い基底部を築き，腰回りの意匠とする近代的な蔵であるが，内部の架構は，登り梁式の伝統的な構法になる。河岸面に建ち並ぶ近隣の土蔵群とともに，かつての湊町の風情を良く残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000799"},{"id":"00004143","register_sub_id":"101","register_pk":"105133","name":"嶋臺書院（古硯堂）","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市中京区御池通烏丸東入仲保利町191","lat":35.01121784,"lng":135.76067232,"geo_status":"db","era":"明治16／昭和27移築","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0169","desc":"敷地の奥に建ち，絲店と中庭を介して向かい合う。昭和２７年に敷地内で移築されている。切妻造，桟瓦葺で，１２畳半の主室と，９畳の次の間からなる。天井をやや低めにとり，栂などの良材を用いた質の高い意匠を備え，欄間彫刻などにも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004143"},{"id":"00002054","register_sub_id":"101","register_pk":"103044","name":"旧徳力彦之助邸（ギャラリー工房・チェリ）","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区太秦組石町2-2","lat":35.01180304,"lng":135.70825583,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造一部鉄筋コンクリート地上2階地下1階建、スレート葺、建築面積187㎡","structure_material":"木造一部鉄筋コンクリート地上2階地下1階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0077","desc":"京福電鉄嵐山本線太秦駅の南方，太秦小学校校庭に面して建つ。漆芸家・徳力彦之助が英国客船の調度品を購入し自ら設計した住宅兼アトリエ。櫻井馬淵建築事務所が実施設計にあたり，チューダーゴシックに仕上げる。傾斜地のためＲＣ造地下室に玄関を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002054"},{"id":"00006164","register_sub_id":"101","register_pk":"107148","name":"樂家住宅茶室麁閑亭","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区油小路通一条下る油橋詰町84","lat":35.02580931,"lng":135.7533689,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0234","desc":"主屋の北側に東西棟で建つ。桁行２間半，梁間１間半の規模で，木造平屋建，切妻造，桟瓦葺とし，東側に庇を張り出す。東側に３畳の茶室，西側に仏間を設け，仏間南面を主屋廊下に繋げる。柱に丸太材を用いるなど，意匠，材料，技術に優れた数寄屋普請とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006164"},{"id":"00004993","register_sub_id":"101","register_pk":"105983","name":"上西家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区浄土寺西田町23-1","lat":35.02681,"lng":135.789978,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡、パーゴラ付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0202","desc":"吉田山東方の神楽岡通沿いの角地に建つ。東西棟の北側に切妻を張出し，東端部に和室を付ける。内部は中廊下式。腰には褐色タイルを波状に張り，菱形桟の窓，く字形に張出す出窓等，多様な窓形式を用いるなど，装飾に意を凝らしたスパニッシュ様式の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004993"},{"id":"00006543","register_sub_id":"101","register_pk":"107526","name":"生谷家住宅主屋","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市上京区室町通鞍馬口下る二丁目竹園町15","lat":35.03617893,"lng":135.75813293,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積151㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0261","desc":"街路に東面する２階建町家。間口４間の切妻造平入で，北側に間口３間の平屋建が付く。１階正面は出格子で飾り，２階は土壁に虫籠窓を開く。内部は南側を通り土間とし，２階背面側に座敷１０畳と次の間７畳半を設ける。烏丸通から入る街路のアイストップとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006543"},{"id":"00013880","register_sub_id":"101","register_pk":"507838","name":"飯田家住宅主屋","kana":"いいだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市鹿野町中園字家ノ下183他","lat":35.48655,"lng":134.05107778,"geo_status":"db","era":"明治後期／大正後期移築増築、昭和45年・同55年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0271","desc":"鹿野城下から旧鹿野町の農村部に移築。二階建切妻造桟瓦葺で四周に下屋を廻す。正面下屋は腕木を屈曲させた出桁造で、跳上げ大戸を残すなど町家の様相を伝える。内部は南に土間、北に三列九室を配し、北西は床付座敷とする。農村景観と一体となった大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013880"},{"id":"00015371","register_sub_id":"101","register_pk":"532495","name":"生田家住宅主屋","kana":"いくたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡南部町東上1010","lat":35.29860833,"lng":133.36528333,"geo_status":"db","era":"明治35年頃／昭和52年・平成15年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積227㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"31 - 0297","desc":"南部町北東の山間に位置する旧家の主屋。敷地中央に南面して建つ入母屋造平入桟瓦葺。内部は東を土間とし、豪壮な梁組をみせ、西に居室を並べる。南西の主座敷は天井を高く張り、庭に面して縁を廻す。床廻りに銘木を用い、欄間の組子など繊細なつくりの主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015371"},{"id":"00012794","register_sub_id":"101","register_pk":"367697","name":"石尾家住宅主屋","kana":"いしおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字大工町南側1687他","lat":35.46143083,"lng":134.06580083,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"31 － 266","desc":"鹿野旧城下の商家で、主屋は旧鹿野往来に北面して建つ。切妻造桟瓦葺のつし二階建で、西側に前庭を囲んで別棟の奥の間と新座敷が連なる。東を土間、西を畳敷の店とし、正面を繊細な格子や出格子、絵様付の腕木で整える。旧城下の街路景観の核となる大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012794"},{"id":"00012795","register_sub_id":"101","register_pk":"367698","name":"石尾家住宅土蔵","kana":"いしおけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字大工町南側1687他","lat":35.46143083,"lng":134.06580083,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"31 － 267","desc":"敷地西北隅に南面して建つ。土蔵造二階建、切妻造桟瓦葺、外壁漆喰塗で、軒は垂木形を表して塗込め、北面を下見板張、西妻を縦板張で養生する。正面は腰海鼠壁で、中央の扉口の鳥居形や土戸を丁寧に仕上げる。旧城下の往来沿いの表構えを重厚に整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012795"},{"id":"00012796","register_sub_id":"101","register_pk":"367699","name":"石尾家住宅門及び塀","kana":"いしおけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字大工町南側1687他","lat":35.46143083,"lng":134.06580083,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.5m 塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"31 － 268","desc":"主屋と土蔵の間の往来沿いに建つ。塀は真壁造の漆喰塗、腰下見板張で、出桁を通して桟瓦葺の屋根をかける。塀東端に開く門は切妻造桟瓦葺の一間腕木門で、扉を弁柄塗とし、欄間に井桁を斜めに入れる。旧城下中心部にある大店の重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012796"},{"id":"00010041","register_sub_id":"101","register_pk":"196188","name":"岩田家住宅主屋","kana":"いわたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市立川町1-94","lat":35.49390802,"lng":134.24205416,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積182㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0184","desc":"鳥取城下の南寄りに位置し、通りに西面する間口八間の町家。奥行一間半の深い下屋正面に出格子をたて、上部に虫籠窓を穿ち、棟に越屋根をあげる。内部は左手を土間として、上手に広めの部屋を二列並べる。赤色瓦や奥行の深い下屋に地方的特色を示す大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010041"},{"id":"00010042","register_sub_id":"101","register_pk":"196189","name":"岩田家住宅茶室","kana":"いわたけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町1-94","lat":35.49378381,"lng":134.24218006,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0185","desc":"主屋南東隅に接続する茶室。主屋根は寄棟造桟瓦葺で、特に庭に面する北東側の柱間装置を開放的な構成とし、吹放しの下屋を廻らす。平面は四畳半茶室と二畳、水屋などからなり、四畳半茶室の西面にトコと茶道口を並べる。落着いた雰囲気の庭空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010042"},{"id":"00010043","register_sub_id":"101","register_pk":"196190","name":"岩田家住宅離れ","kana":"いわたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市立川町1-94","lat":35.49374794,"lng":134.24229601,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"31 － 0186","desc":"茶室東側に渡り廊下を介して建つ。木造平屋建、寄棟造桟瓦葺で、六畳主室を庭のある北側に向けて北東面に縁と下屋を廻らし開放的な形式とする。南面は通りに面するため、土塗大壁として腰を竪板張目板打とする。茶室とともに良好な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010043"},{"id":"00003302","register_sub_id":"101","register_pk":"104292","name":"遠藤家住宅表門","kana":"えんどうけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町坊領486","lat":35.45793993,"lng":133.49140776,"geo_status":"db","era":"万延1","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0060","desc":"屋敷東辺のほぼ中央にあり，小屋内の棟札より年代がわかる。間口３．９ｍ，切妻造・桟瓦葺で，棟通りに柱４本を配し，中央に門口を構えて両側を潜戸と板壁とし，両端の柱前後に控柱を立てる。当地方に多くみられる形式だが，旧家に相応しい規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003302"},{"id":"00003304","register_sub_id":"101","register_pk":"104294","name":"遠藤家住宅家財蔵","kana":"えんどうけじゅうたくかざいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町坊領486","lat":35.45789193,"lng":133.49098748,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0062","desc":"主屋の西方，敷地奥に建つ。２階建土蔵で，南北棟の切妻造・桟瓦葺，正面の東に庇を設ける。１階は中央で南北に間仕切り，北を米蔵とした。外壁は南・北・西の３面を下見板で覆うが，東面は漆喰塗で，２階窓の左右に海鼠壁を廻すなど，つくりが丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003304"},{"id":"00003301","register_sub_id":"101","register_pk":"104291","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町坊領486","lat":35.45797476,"lng":133.4912195,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積264㎡、中門及び塀折れ曲り9m付","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0059","desc":"広大な敷地中央に東面して建つ。寄棟造・平入，茅葺屋根を鉄板で覆っている。食い違い四間取型の平面や構造形式などから，年代は江戸後期と推定され，広間と客間の間に設けた式台玄関などに格式の高さが伺える。規模も雄大で，地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003301"},{"id":"00003305","register_sub_id":"101","register_pk":"104295","name":"遠藤家住宅通用門","kana":"えんどうけじゅうたくつうようもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県西伯郡大山町坊領486","lat":35.45825749,"lng":133.4912394,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口1.8m、塀延長27m付","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0063","desc":"約３千坪の広大な屋敷の東辺に設けられた簡素な腕木門で，屋根は桟瓦葺とする。これより真壁造の塀が北に延び，西に折れて北辺を画する。塀の一部が後世の改築により途切れているものの，通用門と塀は大規模な屋敷の構えに欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003305"},{"id":"00003303","register_sub_id":"101","register_pk":"104293","name":"遠藤家住宅離れ座敷","kana":"えんどうけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町坊領486","lat":35.45800011,"lng":133.49136774,"geo_status":"db","era":"万延1","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"31 － 0061","desc":"表門北側に並んで建ち，棟札から表門と同時の建立で，もと隠居部屋と思われる。木造平屋建，切妻造・桟瓦葺で，通り側の東面に格子窓，敷地側に玄関を設け，内部は玄関から延びる中央通路を挟んで左右に６畳間を配する。旧家の屋敷構成を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003303"},{"id":"00007284","register_sub_id":"101","register_pk":"108266","name":"桜寛苑（旧金田家住宅）主屋","kana":"おうかんえん（きゅうかねだけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町2-301","lat":35.50646355,"lng":134.236206,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積157㎡","structure_material":"木造2階一部平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"31 － 0114","desc":"鳥取城跡の西方、堀を介した敷地に建つ住宅。階高の高い木造２階建で、平面は中廊下式である。和風を基調とするが、２階洋間と１階居間は洋風の意匠でまとめ、１階南側にはサンルームを設けている。内装・外装とも質の高い、昭和初期の和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007284"},{"id":"00007285","register_sub_id":"101","register_pk":"108267","name":"桜寛苑（旧金田家住宅）土蔵","kana":"おうかんえん（きゅうかねだけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町2-301","lat":35.50653814,"lng":134.23611328,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"31 － 0115","desc":"主屋の北面西寄りに、渡廊下を介して建つ土蔵。２階建、切妻造桟瓦葺で、外壁上部から軒を漆喰で塗り込め、下部を高く竪板張とする。桁行４．９ｍ梁間３．９ｍ規模で、内壁は竪板張、２階床を張り、南東隅に階段を設ける。妻面に庇をかけて小窓を開いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007285"},{"id":"00007286","register_sub_id":"101","register_pk":"108268","name":"大井家住宅主屋","kana":"おおいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市気高町上光字扇子間392-1","lat":35.481197,"lng":134.0784,"geo_status":"db","era":"江戸末期／明治38・平成13移築改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"31 － 0116","desc":"鳥取市西方に所在する住宅。正面間口１７ｍ奥行１４ｍ規模の２階建。東西棟の切妻造桟瓦葺で、背面中央に切妻屋根を付設。東寄りに土間を設け、床上部は六間取とし、南側にミセノマとブツマ、ショインを並べる。木柄も太く、重厚な梁組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007286"},{"id":"00011792","register_sub_id":"101","register_pk":"210808","name":"太田家住宅主屋","kana":"おおたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡八頭町富枝字下土居屋敷40","lat":35.363179,"lng":134.359204,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積231㎡","structure_material":"木造2階一部平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"31-0226","desc":"木造二階建で、南東隅に土間玄関を取り、床上部は二列各三室を基本とするが、庭に面した背面側は雁行する内縁を廻らす。表側二階への階段は土間部に設ける。座敷廻りを中心に良材を多用し、各部を透漆仕上げとするなど上質な造りで、大規模近代和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011792"},{"id":"00011793","register_sub_id":"101","register_pk":"210809","name":"太田家住宅新建","kana":"おおたけじゅうたくしんだて","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡八頭町富枝字下土居屋敷40","lat":35.363309,"lng":134.359174,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"31-0227","desc":"主屋背面西端に接続する木造平屋建で、周囲に下屋庇を廻らす。入母屋造桟瓦葺で、北から座敷八畳、四畳、六畳を並べ、北東南の三方に広縁を廻らす。付書院が付く床廻りの意匠、天井の高い内法、ヒノキやスギ・マツの良材を多用する点など、質の高い離れである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011793"},{"id":"00011794","register_sub_id":"101","register_pk":"210810","name":"太田家住宅門長屋","kana":"おおたけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡八頭町富枝字下土居屋敷40","lat":35.363065,"lng":134.35928,"geo_status":"db","era":"明治30年頃／大正4年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"31-0228","desc":"敷地南端を画す門長屋。入母屋造桟瓦葺で、切石積の基礎に腰部は豆砂利洗い出し、上部は白漆喰塗とする。西端に門口を開き、東に居室を配する構成で、東端室は大正四年の郵便局開局に際して改造され、内部にカウンター等を備えるが、外観は旧状を留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011794"},{"id":"00005659","register_sub_id":"101","register_pk":"106647","name":"加藤家住宅主屋","kana":"かとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市倭文491","lat":35.444366,"lng":134.200745,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"31 － 0103","desc":"敷地の中央に東面して建つ。桁行８間半，梁間５間半規模，入母屋造，もと茅葺。北方を土間，南方を床上部とし，東面中央に式台を設け，南面に数寄屋風の便所を突き出す。内部は東南部を８畳座敷とし，当初は８畳と４畳を配した広間型五間取と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005659"},{"id":"00012623","register_sub_id":"101","register_pk":"367917","name":"金平家住宅主屋","kana":"かねひらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字太一垣字宮ノ前179","lat":35.47752,"lng":133.610367,"geo_status":"geocoded","era":"明治18年／昭和50年・同51年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、茅葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0257","desc":"大山裾野の田園地帯にある農家で、主屋は敷地中央に西面して建つ。桁行七間梁間五間、寄棟造茅葺で桟瓦葺の箱棟を載せる。内部は北に土間、南に二列計五室を配し、南列表に座敷飾を備えたオモテを設ける。伯耆地方平野部の伝統的な農家建築の形式をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012623"},{"id":"00010234","register_sub_id":"101","register_pk":"198067","name":"木島家住宅主屋","kana":"きしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡若桜町大字若桜字中町298","lat":35.343503,"lng":134.397997,"geo_status":"db","era":"明治20頃／平成24改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積153㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"31 － 0191","desc":"若桜街道に西面して建つ木造二階建で、切妻造鉄板葺とする。正面の瓦葺の下屋は仮屋と称する通路で、南寄りに戸口を開く。内部は南が土間で、床上は二列六室とし、土間寄り中室は土間と一連の吹抜けとする。北西の座敷八畳は付書院を設けて丁寧な造作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010234"},{"id":"00002091","register_sub_id":"101","register_pk":"103081","name":"旧塩屋出店納屋","kana":"きゅうしおやでみせなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26964731,"lng":134.22934982,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0039","desc":"洋館の東方に接し，洋館のやや振れた棟方向に揃えて建つ。桁行３間半，梁行１間規模，木造平屋建，切妻造，桟瓦葺の納屋で，南北両平側面の中央に出入口を設ける。簡素な小屋であるが，洋館とともに屋敷構えの発展過程を知るうえで必要な構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002091"},{"id":"00002090","register_sub_id":"101","register_pk":"103080","name":"旧塩屋出店洋館","kana":"きゅうしおやでみせようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭545","lat":35.26969562,"lng":134.2293005,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積25㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"31 － 0038","desc":"東西にやや長い敷地のほぼ中央南寄りに位置し，主屋の南東端から東方に突き出たカマヤ部の東方に建つ。木造２階建，下見板張，切妻造，桟瓦葺の洋館で，窓の額縁を柱型として表すなどスティックスタイル風の意匠をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002090"},{"id":"00013884","register_sub_id":"101","register_pk":"507842","name":"旧髙多家住宅主屋","kana":"きゅうたかたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市河原町1879-１","lat":35.42934167,"lng":133.81086667,"geo_status":"db","era":"明治35年／大正前期、昭和43年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積140㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0275","desc":"打吹山西方にある商家。道路に北面して建つ平屋建切妻造桟瓦葺で、正面に下屋を付す。外壁は真壁造黒漆喰塗で間口一杯を開口とする。東に土間、西に二列六室を配して南西を床付の座敷とし、南に縁を通す。たちの低い古式なつくりで旧商家町の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013884"},{"id":"00013883","register_sub_id":"101","register_pk":"507841","name":"旧外江屋店舗（米子まちなか観光案内所）","kana":"きゅうとのえやおもや（よなごまちなかかんこうあんないしょ）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"鳥取県","address":"鳥取県米子市灘町一丁目19他","lat":35.43323611,"lng":133.32474167,"geo_status":"db","era":"慶応2年(1866年)／昭和34年頃・平成30年改修","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0274","desc":"米子城跡北方にある元海産物問屋店舗。道路に東面する緩勾配の切妻造桟瓦葺で、背面に別棟の二階建接続。外壁は真壁造中塗仕上。北に通り土間、南に元は二列六室を配し、南西座敷には奥行の浅い床を付す。二階のたちが高く、近世の米子町家を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013883"},{"id":"00013178","register_sub_id":"101","register_pk":"368307","name":"旧富士市橋家住宅主屋","kana":"きゅうふじいちはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県東伯郡湯梨浜町小鹿谷字御屋敷前264","lat":35.45904167,"lng":133.90337778,"geo_status":"db","era":"大正10年／平成27年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"31 － 0270","desc":"湯梨浜町中部の農村地帯に位置する、元地主の住宅。敷地中央に北面して建ち、入母屋造の屋根に赤色の桟瓦を葺き、四周に下屋を廻らす。内部は西側を居室部として、北に吟味された木材を使用した客間を設ける。狭い土間など、近代的な発展を見せる農家住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013178"},{"id":"00005496","register_sub_id":"101","register_pk":"106484","name":"旧藤原家住宅主屋","kana":"きゅうふじわらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬1947","lat":35.29083608,"lng":134.24939654,"geo_status":"db","era":"明治末期／大正末期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋一部2階建、鉄板葺及び瓦葺、建築面積110㎡、味噌蔵付","structure_material":"木造平屋一部2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0101","desc":"板井原川を背にほぼ南面して建つ。東西棟の切妻造で，南と北に下屋をかけ，東側を２階建とし，当初の屋根は茅葺であった。１階は西に土間を配した広間型三間取を基本とし，２階は大正末期頃に増築され蚕室として使用。変則的な外観が生業の変遷を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005496"},{"id":"00005497","register_sub_id":"101","register_pk":"106485","name":"旧藤原家住宅土蔵","kana":"きゅうふじわらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬1947","lat":35.29082798,"lng":134.24948067,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、鉄板葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0102","desc":"主屋の東側面に並んで建つ。１辺約４ｍの方形平面になる土蔵造２階建で，屋根は東西棟の切妻造である。１階は土間で庇が付く南に観音開の扉を設け，２階は板敷で南に窓を開ける。外壁が荒壁仕上で，屋根は置屋根式とする。柱を密に立てて堅牢なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005497"},{"id":"00016601","register_sub_id":"101","register_pk":"574963","name":"久代家住宅主屋","kana":"くしろけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県日野郡日南町霞字福長サ682","lat":35.16903056,"lng":133.32429417,"geo_status":"db","era":"江戸後期／明治後期・昭和前期・同30年代・同44年増築、平成11年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積321㎡、庭門付","structure_material":"木造平屋一部2階建","registered":"2026.02.10(令和8.02.10)","register_no":"31 - 0302","desc":"日野往来沿いの集落にある旧家の主屋。敷地中央に北面して建つ平屋建切妻造桟瓦葺で北東に角屋、南にナンドと台所を突出する。座敷は床、神棚付床脇、付書院を備え、長押に皮付材を用い上質な数寄屋風の意匠とする。大規模な主屋が地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016601"},{"id":"00016602","register_sub_id":"101","register_pk":"574964","name":"久代家住宅長屋門","kana":"くしろけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県日野郡日南町霞字福長サ682","lat":35.16903056,"lng":133.32429417,"geo_status":"db","era":"明治前期／平成11年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"31 - 0303","desc":"主屋の北側に位置する長屋門。北面して建つ平屋建片入母屋造桟瓦葺で外壁は漆喰塗、腰は簓子下見板張とする。桁行中央を門口とし、東に座敷、西に物置や馬屋などを配する。座敷は床、床脇、平書院を備えた上質なつくり。大庄屋の格式を示す桁行長大な長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016602"},{"id":"00011395","register_sub_id":"101","register_pk":"209232","name":"熊谷家住宅主屋","kana":"くまがいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字下町南側1393-5","lat":35.461813,"lng":134.061911,"geo_status":"db","era":"江戸末期／昭和18・同32改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積162㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"31－0210","desc":"鹿野旧城下の中央やや西寄りに位置する町家。通りに西面して建つ。軒の低いつし二階で右土間とし、南北二列各三室の床上部を持つ。北列は中室をブツマ、東・西室とも床付のザシキとする。北列西室表側には千本格子を嵌め、鹿野の町並みを特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011395"},{"id":"00015503","register_sub_id":"101","register_pk":"533518","name":"後藤家住宅離れ（長楽軒）","kana":"ごとうけじゅうたくはなれ（ちょうらくけん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市内町153他","lat":35.43261389,"lng":133.32406944,"geo_status":"db","era":"明治40年頃／昭和44年移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"31 - 0299","desc":"重文後藤家住宅の隣地に位置する離れ座敷。続き間座敷の北東に玄関と三畳の松風庵、北西に広縁を廻らす。主座敷は床・琵琶床・棚を備えた自由な構成で、松風庵は上部に枝を付したナンテンを床柱に用いるなど凝ったつくり。随所に良材を用いた上質な離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015503"},{"id":"00007658","register_sub_id":"101","register_pk":"108640","name":"坂口家住宅主屋","kana":"さかぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市尾高町13他","lat":35.43154473,"lng":133.32860625,"geo_status":"db","era":"明治25／大正期・昭和前期改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0142","desc":"敷地の西北角に位置する。東西９．６ｍ南北１６ｍ、東西棟の２階建で、東面南寄りに平屋建の台所棟、北寄りに玄関を設ける。大棟は西切妻造で、西面に落棟の入母屋屋根を造り、北面に下屋庇をまわすなど複雑な屋根を構成し、豊かな街路景観を生み出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007658"},{"id":"00007661","register_sub_id":"101","register_pk":"108643","name":"坂口家住宅土蔵","kana":"さかぐちけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市尾高町13他","lat":35.43130939,"lng":133.3284062,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0145","desc":"敷地南端、米子城の旧外堀に面する。東西棟の切妻造桟瓦葺、桁行８．６ｍ梁間５．０ｍの土蔵造２階建。北正面は腰高に海鼠壁とする。旧外堀側は高く竪板を張り、２階に２ヶ所、１階に１ヶ所の庇付窓を穿ち、土蔵が建ち並ぶ旧外堀沿いの景観の一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007661"},{"id":"00007660","register_sub_id":"101","register_pk":"108642","name":"坂口家住宅土間倉","kana":"さかぐちけじゅうたくどまぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市尾高町13他","lat":35.4313678,"lng":133.32853907,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋一部地下1階建、瓦葺、建築面積26㎡","structure_material":"木造平屋一部地下1階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0144","desc":"敷地東側の中ほど、主屋台所の南方に建つ。桁行１１ｍ梁間３．０ｍの木造平屋一部地下１階建、北側に便所を付ける。南半部に土間の納屋、北半部に床や棹縁天井を張る部屋を設ける。地下室は部屋下で、炭や漬物を置く。真壁造の漆喰仕上げに腰まで竪板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007660"},{"id":"00007659","register_sub_id":"101","register_pk":"108641","name":"坂口家住宅離れ及び渡廊下","kana":"さかぐちけじゅうたくはなれおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市尾高町13他","lat":35.4314168,"lng":133.32843259,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0143","desc":"主屋から渡廊下を介して離れへ繋がる。離れは東西６．１ｍ南北６．９ｍの木造平屋建で、Ｔ字型に交わる入母屋屋根とし、下屋庇をまわす。小規模ながら変化に富む外観。渡廊下は桁行１４ｍで便所を付ける。西面は外塀を兼ねており、伝統的な通りの佇まいを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007659"},{"id":"00007662","register_sub_id":"101","register_pk":"108644","name":"坂口家住宅門及び塀","kana":"さかぐちけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県米子市尾高町13他","lat":35.43159551,"lng":133.32870263,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、瓦葺、間口1.6m、塀 木造、瓦葺、総延長6.9m","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0146","desc":"北側街路に面して主屋の東に、木造桟瓦葺の門と塀が建つ。門は間口１．６ｍ、切妻造の一間腕木門で、両開戸を吊る。塀は門の両脇に設けられ、総延長６．９ｍ。切石基礎上、方柱を建て、腕木が軒を支持する。白漆喰仕上げで腰高に竪板を張り、表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007662"},{"id":"00012023","register_sub_id":"101","register_pk":"210964","name":"佐々木家住宅穀蔵","kana":"ささきけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県日野郡日野町舟場字間地殿ノ上エ357","lat":35.245876,"lng":133.444245,"geo_status":"db","era":"文政12年（1829）","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-242","desc":"主屋前方の南西にあり北面する。置屋根形式で、切妻造、妻入とし、正面に下屋庇を付ける。扉口を二所設け、内部は一階を二室に区切り、二階を一室とする。東側の扉口には石製の楣を用いる。主屋と同時期の建築で、大規模農家の生活を支える土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012023"},{"id":"00012021","register_sub_id":"101","register_pk":"210962","name":"佐々木家住宅主屋","kana":"ささきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県日野郡日野町舟場字間地殿ノ上エ357","lat":35.246023,"lng":133.44423,"geo_status":"db","era":"江戸後期／明治中期・昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-240","desc":"日野川沿いの舟場集落にある敷地奥に南面する。つし二階建、切妻造、桟瓦葺で、東半を広い土間とし、西半の床上部は食違い四間取で、正面からオモテ側面まで矩折に縁を廻す。床の間の意匠や差鴨居の成などに江戸後期の特徴がみられ、古式をよく留める近世民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012021"},{"id":"00012024","register_sub_id":"101","register_pk":"210965","name":"佐々木家住宅新蔵","kana":"ささきけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県日野郡日野町舟場字間地殿ノ上エ357","lat":35.245891,"lng":133.444352,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-243","desc":"主屋前方の南東にあり北面する。置屋根形式で、切妻造、平入とし、正面に下屋庇をつける。内部は一、二階とも一室で、柱を密に立てた堅牢な造りとする。正面は、扉口や二階窓の観音扉に木瓜形を表し、下屋庇上部を海鼠壁で飾り、敷地景観を良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012024"},{"id":"00012022","register_sub_id":"101","register_pk":"210963","name":"佐々木家住宅新座敷","kana":"ささきけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県日野郡日野町舟場字間地殿ノ上エ357","lat":35.245981,"lng":133.444117,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-241","desc":"主屋の西に渡廊下を介して続く新座敷。南北棟の切妻造、桟瓦葺。南面に式台玄関を設け、北に六畳と一〇畳の二室を配し、西側に縁を廻す。南には風呂や便所を付ける。一〇畳間は、床の間、床脇、付書院を備えた上質な座敷で、板欄間彫刻も見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012022"},{"id":"00010883","register_sub_id":"101","register_pk":"201718","name":"塩谷定好写真記念館ギャラリー棟","kana":"しおたにていこうしゃしんきねんかんぎゃらりーとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字赤碕1561","lat":35.513572,"lng":133.650749,"geo_status":"db","era":"明治7／昭和中期・平成26改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0206","desc":"主屋東隣に連続して建つ木造二階建、東西棟の切妻造桟瓦葺、外壁漆喰塗で、正面に吹放しの下屋を通す。当初は蔵として使い、戦後店舗兼スタジオに改修し、現在は西妻面で主屋と連絡する。小屋は登梁形式である。主屋と調和した外観をもち、町並景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010883"},{"id":"00010884","register_sub_id":"101","register_pk":"201719","name":"塩谷定好写真記念館米蔵","kana":"しおたにていこうしゃしんきねんかんこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字赤碕1561","lat":35.513495,"lng":133.650753,"geo_status":"db","era":"明治5／平成26改修","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0207","desc":"ギャラリー棟の南に建ち、土蔵造二階建、南北棟の切妻造桟瓦葺で、西に小窓を穿つ。外壁は竪板張で鉢巻を廻らすが、もとは腰を海鼠壁としていた。一部だけに設けた二階床、鉄板を張った内壁など、内部に米蔵らしさを残す土蔵で、屋敷東境の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010884"},{"id":"00010885","register_sub_id":"101","register_pk":"201720","name":"塩谷定好写真記念館質蔵","kana":"しおたにていこうしゃしんきねんかんしちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字赤碕1561","lat":35.513436,"lng":133.650756,"geo_status":"db","era":"明治12／平成26改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0208","desc":"二階建の土蔵造、南北棟の桟瓦葺で、西面に下屋を架けて扉口を設ける。外壁は上部漆喰塗、腰を海鼠壁とするが、両側面と背面は竪板張である。来待石切石四段積の基礎、扉口上部の波涛文の鏝絵など施工も丁寧。敷地内で最大の土蔵で、屋敷後方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010885"},{"id":"00010882","register_sub_id":"101","register_pk":"201717","name":"塩谷定好写真記念館主屋","kana":"しおたにていこうしゃしんきねんかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字赤碕1561","lat":35.513553,"lng":133.650713,"geo_status":"db","era":"明治39／平成26改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積192㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0205","desc":"海岸沿いを東西に通る街道に北面する商家建築。東西棟の二階建、切妻造桟瓦葺。外壁は漆喰塗で正面の上下階に広く繊細な格子をたてる。二階にも座敷を多数配し、銘木や螺鈿を用いた座敷の造作は上質である。当初形式をよく残し、町並景観の重要な存在となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010882"},{"id":"00010886","register_sub_id":"101","register_pk":"201721","name":"塩谷定好写真記念館新蔵","kana":"しおたにていこうしゃしんきねんかんしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字赤碕1561","lat":35.513443,"lng":133.65069,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0209","desc":"敷地南辺、庭を挟んで主屋と対面し、土蔵造二階建、東西棟の桟瓦葺で、小屋組は登梁形式である。北面に庇を架けて観音扉口を設け、外壁は上部を漆喰塗、腰を海鼠壁とし、内壁は竪板張である。敷地内に現存する蔵では最も新しく、屋敷構成の充実過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010886"},{"id":"00006279","register_sub_id":"101","register_pk":"107263","name":"高砂屋（城下町とっとり交流館）蔵一","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）くらいち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.49899848,"lng":134.23719252,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0106","desc":"東西２棟の土蔵を蔵前で接続した形式で，主屋後方に建つ。東蔵は桁行９ｍ，梁間４ｍ，西蔵は桁行６ｍ，梁間４ｍ，両蔵とも２階建，切妻造，桟瓦葺。１・２階の正面腰部を七宝模様の海鼠壁とし，扉まわりや窓庇の持送りに漆喰彫刻を施し，見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006279"},{"id":"00006298","register_sub_id":"101","register_pk":"107281","name":"高砂屋（城下町とっとり交流館）蔵三","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）くらさん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.49911414,"lng":134.237045,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0108","desc":"主屋後方の西寄りに建つ土蔵。桁行５ｍ，梁間４ｍ，２階建，切妻造，桟瓦葺。正面に下屋を葺き下ろして蔵前とする。１・２階の正面腰部を海鼠壁とし，他の面は縦板張とする。正面下屋や２階窓庇は垂木形をみせた塗籠とし，窓庇の持送りに渦紋の漆喰彫刻を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006298"},{"id":"00006297","register_sub_id":"101","register_pk":"107280","name":"高砂屋（城下町とっとり交流館）蔵二","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）くらに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.49907776,"lng":134.23711248,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0107","desc":"主屋後方に建つ土蔵。桁行６ｍ，梁間４ｍ，２階建，切妻造，桟瓦葺。正面に下屋を葺き下ろす。正面腰部を海鼠壁とし，他の面は縦板張や鉄板張とする。平入形式で，両側に建つ妻入形式の蔵一，蔵三と好対照をなし，屋敷景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006297"},{"id":"00006599","register_sub_id":"101","register_pk":"107582","name":"高砂屋（城下町とっとり交流館）住居棟","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）じゅきょとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.498936,"lng":134.236984,"geo_status":"db","era":"明治初期／平成16曳家","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0105","desc":"店舗棟の西隣、街道に面して建ち、店舗棟より半間前面に間口を構える。建築面積８５㎡、木造２階建，桟瓦葺。店舗棟に比して簡素な外観であるが、上下の軒裏や２階部分の正面は漆喰塗とし、袖卯建を上げるなど、耐火性に配慮した重厚な構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006599"},{"id":"00006299","register_sub_id":"101","register_pk":"107282","name":"高砂屋（城下町とっとり交流館）脇門","kana":"たかさごや（じょうかまちとっとりこうりゅうかん）わきもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市元大工町1","lat":35.498848,"lng":134.237061,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"31 － 0109","desc":"主屋東側前寄りに附属し，前面の街道と主屋東庭を仕切る。門口１ｍの腕木門形式で，内開板戸を吊る。屋根を左右に延長して，総延長２．６ｍの漆喰塗土塀の外観とし，切妻造，桟瓦葺で，腰下を下見板張とする。主屋と同じ瓦を用いて外観の統一を図っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006299"},{"id":"00012620","register_sub_id":"101","register_pk":"367914","name":"高田家住宅主屋","kana":"たかたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字大工町南側1644","lat":35.458935,"lng":134.062576,"geo_status":"geocoded","era":"江戸末期／明治25年・平成11年改修、昭和前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積200㎡、内庭戸口及び塀付","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0254","desc":"旧鹿野往来西端の角地に北面して建つ酒造販売を営んだ町家。切妻造桟瓦葺の二階建で、西半の土間や店の間は梁組を現す。東半に四室を配し、背面に離れを接続する。幅一間の広い下屋や正面に並ぶ格子などが特徴的な表構えで、伝統的な街道景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012620"},{"id":"00000604","register_sub_id":"101","register_pk":"101594","name":"立川吉村家住宅勝手蔵","kana":"たちかわよしむらけじゅうたくかってぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.49171159,"lng":134.24613606,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺，建築面積124㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0026","desc":"屋敷地の東北隅に建つ内向きの建物で，内側に土庇を置く。日用品を収めた土蔵と東側の味噌蔵及びその間の元女中部屋が，一体的に建ち並ぶ。豪商の生活の一面を知る上で欠かせない存在であるが，漆喰仕上げの外壁に縦板を貼り，路地筋の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000604"},{"id":"00000605","register_sub_id":"101","register_pk":"101595","name":"立川吉村家住宅米蔵","kana":"たちかわよしむらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.49176667,"lng":134.24634852,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺，建築面積206㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0027","desc":"敷地北側の路地に沿って，米穀商も営んだ吉村家の隆盛ぶりを物語る木造２階建の中小規模の土蔵３棟が一体的に建ちならぶ。それぞれ裏庭側に開口部を設け，前面に土庇を置く。路地側の外壁は縦板貼とし，勝手蔵や付属棟とも町筋の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000605"},{"id":"00000602","register_sub_id":"101","register_pk":"101592","name":"立川吉村家住宅什器蔵","kana":"たちかわよしむらけじゅうたくじゅうきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.49162012,"lng":134.24620688,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺，建築面積36㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0024","desc":"主屋玄関の北脇に主屋と接して建つ小規模な土蔵で，前後に庇が付く形式になる。外壁を漆喰仕上げとし，腰板貼りとする外観は主屋と一体的な構成になる。昭和１１年の道路拡幅で主屋ととも曳屋され，蔵の向きを現状に改めたと伝えるが，違和感はない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000602"},{"id":"00000601","register_sub_id":"101","register_pk":"101591","name":"立川吉村家住宅主屋","kana":"たちかわよしむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.4915611,"lng":134.24632295,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造２階建，瓦葺，建築面積311㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0023","desc":"切妻造，２階建の大規模な主屋で，中廊下を挟んで居室及び玄関が配され，北面に台所，南面に書斎，西面に板塀が附属する。大棟及び一間幅の庇はともに石州瓦葺で，２階をなまこ壁とし軒裏を漆喰で塗り込める外観はよく目立ち，地区の象徴的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000601"},{"id":"00000603","register_sub_id":"101","register_pk":"101593","name":"立川吉村家住宅通用門","kana":"たちかわよしむらけじゅうたくつうようもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.49164176,"lng":134.24614983,"geo_status":"db","era":"明治中期／昭和11曵屋","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"屋根塀延長7.4m，門口一所付属","structure_material":"屋根塀延長7.4m","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0025","desc":"什器蔵の北側にあり，勝手蔵との間を塞ぐ屋根塀の中央部に間口１間半の門口を開いたもの。門口の左右は真壁造，腰板貼りとする簡素な構造になる。門口は元間口１間であったが，近年車の出入りのため広げられた。屋敷構えを構成する要素の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000603"},{"id":"00000606","register_sub_id":"101","register_pk":"101596","name":"立川吉村家住宅付属棟","kana":"たちかわよしむらけじゅうたくふぞくとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市立川町4-140","lat":35.49176766,"lng":134.2465836,"geo_status":"db","era":"明治中期／昭和11曵屋","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建，瓦葺，建築面積69㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"31 － 0028","desc":"米蔵から続く路地境奥側に建つ木造平屋建の建屋。大工・左官作業場及び番頭部屋から構成される。大工・左官作業場は，出入りの大工らが建屋の維持修理作業を日常的に行ったところで，吉村家住宅の建物群の維持管理を知る上でも欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000606"},{"id":"00012011","register_sub_id":"101","register_pk":"210952","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字鍛冶町西裏1408他","lat":35.462267,"lng":134.061855,"geo_status":"db","era":"江戸末期／昭和18年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-230","desc":"南北街路に東面して建つ。切妻造桟瓦葺平入のつし二階建の町家。南側を土間とする1列三室と小規模で背面に角屋を出す。文久年間の建築と伝わる。二階は板葺から瓦葺に改めた際に天井を上げて整備したもの。腕木彫刻など鹿野地区の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012011"},{"id":"00014080","register_sub_id":"101","register_pk":"508340","name":"津中家住宅主屋","kana":"つなかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字大工町北側1600他","lat":35.46289444,"lng":134.05856111,"geo_status":"db","era":"明治37年／昭和18年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"31 - 0276","desc":"城下町鹿野の西側に位置する町家で鹿野祭の御旅所。通りに南面する二階建切妻造桟瓦葺。内部は東を土間、西を二列四室、二階は三列六室を並べる。建ちが高く、二階はガラス戸の連窓で開放的な外観とする。正面下屋は屈曲した腕木で軒を支え、地域色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014080"},{"id":"00012448","register_sub_id":"101","register_pk":"531772","name":"林田家住宅米蔵","kana":"はやしだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町岡益下土居173","lat":35.45353056,"lng":134.2953,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積46㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"31-245","desc":"主屋の前方西隅に南面して建ち、切妻造平入で正面に土庇をかける。外壁は漆喰仕上、腰下見板張の伝統形式だが、正面は腰壁をモルタルで石張風とし、土庇に円柱を用いて腰を人造石仕上とするなど洋風意匠を取入れる。近代の大規模民家の屋敷構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012448"},{"id":"00012447","register_sub_id":"101","register_pk":"531771","name":"林田家住宅主屋","kana":"はやしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町岡益下土居173","lat":35.45345,"lng":134.2955,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積318㎡","structure_material":"木造平屋一部2階建","registered":"2018.05.10(平成30.05.10)","register_no":"31-244","desc":"鳥取市郊外の集落にあり、主屋は敷地中央に北面して建つ。入母屋造平入で四周に下屋を廻らし、正面に入母屋の式台玄関を突出する。内部は七間取で、庭側の前面に座敷を並べ、上質な用材と座敷飾で設える。伝統木造建築の近代的展開を示す大規模住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012447"},{"id":"00011396","register_sub_id":"101","register_pk":"209233","name":"原田家住宅主屋","kana":"はらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市鹿野町鹿野字下町南側1344他","lat":35.461951,"lng":134.062748,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積173㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"31－0211","desc":"鹿野旧城下の中央に位置する二階建町家。通りに北面して建つ。右土間で、東西二列に室を並べる。東列は中室をブツマ、南・北室をザシキとする。土間境に「大角」「横角」と呼ぶ太い梁と桁を入れ、その太さで家の興隆を示す、鹿野の歴史的景観を特徴づける建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011396"}];
